(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-vae-decode-2bit-latent"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-1\">一 · 事故现场：首帧卡在 VAE 解码上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-2\">二 · 它解决什么：解码端的两个可动变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-3\">三 · 它不解决什么：三条明确的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-4\">四 · 一个具体例子：从整帧解码到流式分块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-5\">五 · 与相邻机制的切分：为什么必须是解码端</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-6\">六 · 边界先于收益：解码端压缩能救什么、救不了什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-7\">七 · 量化写入 latent 缓存：分组、scale 与残差留存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-8\">八 · 时间块流式读取与异步拷贝重叠</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-9\">九 · 时间上采样：重叠帧上下文融合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-10\">十 · 空间 tile 分块解码与 halo 重叠</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-11\">十一 · 首层残差补偿与按帧流式输出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-12\">十二 · 步骤间的耦合与失败模式定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-13\">十三 · 解码数据流上的四道关卡：量化写缓存、异步卷积、重叠融合与 halo 分块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-14\">十四 · 分组量化：从连续 latent 到可缓存整数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-15\">十五 · 解码时延的双约束：算力与带宽取大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-16\">十六 · 伪代码：量化写入与流式解码主循环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-17\">十七 · 显存账：latent 缓存与 batch 上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-18\">十八 · 误差传播：残差补偿与接缝、闪烁的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-19\">十九 · 与采样端并行轴的分离及规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-20\">二十 · 失效边界：量化误差、halo 比例与同步点的三重约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-21\">二十一 · 请求形态的匹配判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-22\">二十二 · 长度分布对批大小与显存预算的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-23\">二十三 · 并发与批大小的实际调节点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-24\">二十四 · 负载不对时的失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-25\">二十五 · 配方与相邻机制的边界划分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-26\">二十六 · 负载配方：长视频流式解码吃得住，短请求与高并发吃不住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-27\">二十七 · 硬件档位：按解码瓶颈选卡，而不是按采样规模选卡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-28\">二十八 · 并行拓扑：帧级数据并行与采样序列并行轴分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-29\">二十九 · 量化方案：per-group scale 的分组粒度决定纹理保真度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-30\">三十 · KV 策略：这里没有 KV，只有滚动回收的 latent 缓存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-31\">三十一 · 调度参数：以首帧时延与帧间隔为 SLO 的两个独立旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-32\">三十二 · 可复现的配置思路：从单卡基线到机柜级的三步走</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-33\">三十三 · 解码端配方的失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-34\">三十四 · 显存驻留与batch上限：先崩的是latent缓存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-35\">三十五 · 带宽与计算受限的切换点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-36\">三十六 · 通信：latent传输与解码并行的拓扑约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-37\">三十七 · 功耗与热约束下的持续吞吐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-38\">三十八 · 尾延迟：规模上去后最先劣化的SLO指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-39\">三十九 · 规模上限由谁决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-40\">四十 · 规模上去以后，先崩的是 latent 带宽与 halo 重复计算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-41\">四十一 · 精度失效的三条链路：分组量化、残差补偿与首层反量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-42\">四十二 · OOM 的真实来源：latent 缓存、halo 工作区与异步拷贝缓冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-43\">四十三 · 批抖动与路由不均：为什么帧间隔会周期性劣化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-44\">四十四 · 尾延迟尖刺：同步点、SMEM 竞争与 tile 边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-45\">四十五 · 监控指标体系与回滚决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-46\">四十六 · 把诊断做成解码循环的一部分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-47\">四十七 · 对照轴：压缩发生在哪一端</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-48\">四十八 · 决策表：六种情形的选型与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-49\">四十九 · 与采样端压缩的耦合条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-50\">五十 · 分块重叠与序列并行的分工线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-51\">五十一 · 精度分配：哪些层不能压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-52\">五十二 · 规模上限与退出条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-decode-2bit-latent-sec-53\">五十三 · 选型边界：什么条件下该走低bit latent解码，什么条件下该退回去</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:518px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 518.5 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"436.5\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样输出的latent按通道分组量化为FP8/低bit并加per-grou…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"436.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">VAE解码器按时间块流式读取latent，异步拷贝到SMEM并与FP8卷积…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"436.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">时间上采样层用重叠帧上下文做融合，消除块边界闪烁。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"436.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">空间上采样按tile分块解码，tile间halo重叠避免接缝。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"436.5\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码像素按帧流式输出，低bit latent反量化残差在解码首层补偿。</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-vae-decode-2bit-latent-sec-1\">一 · 事故现场：首帧卡在 VAE 解码上</h3>\n<p>某高分辨率长视频流式服务上线后，采样侧一切正常：DiT 主干在 Blackwell 上按块推进，latent 按时产出。但端到端 SLO 反复被击穿，且击穿点不在采样，而在采样之后的那一段——VAE 解码。表现是：首帧时延远超预算，帧间隔抖动大；批大小一调大，显存立刻告急；把批调小，吞吐又塌下去。工程上把这段链路拆开看，问题非常具体：latent 通道多、时空维度大，解码卷积与注意力层是访存密集型，HBM 读写把解码压在带宽受限区间；同时 latent 缓存本身占用高，挤占了 batch 与解码工作区的显存预算。用材料给出的两个关系式可以直接定位瓶颈：</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{latent}}\\approx \\frac{C'\\,H'\\,W'\\,T}{\\text{compression}}\\cdot b_{\\text{latent}},\\quad T_{\\text{decode}}\\approx \\max\\left(\\frac{\\text{FLOPs}_{\\text{VAE}}}{\\text{TC}_{\\text{FP8}}},\\ \\frac{\\text{Bytes}_{\\text{latent}}}{\\text{BW}}\\right)$$</div>\n<p>第一式说明：在压缩比与 latent 位宽不变时，显存随分辨率与时长线性上涨，latent 缓存越大，能同时驻留的请求越少，batch 上限被显存而不是算力卡死。第二式说明：解码时延取“算力项”与“带宽项”的较大者。事故中的解码落在带宽项上——FP8 张量核的算力没有被用满，时间花在把 latent 与中间特征在 HBM 与 SMEM 之间搬运。这就是为什么单纯加卡、加 batch 都救不了首帧：瓶颈是每字节的搬运成本，不是每秒的浮点运算。事故的根因因此可以归为两条：latent 传输与缓存占用过高，以及解码访存密集导致的带宽受限。这个失败案例划出了本算法要解决的问题边界——它要动的不是采样端的序列并行或显存优化，而是解码端的 latent 表示与解码执行方式。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-2\">二 · 它解决什么：解码端的两个可动变量</h3>\n<p>把问题收敛到可操作的变量上，只有两个旋钮：latent 的“体积”和解码的“执行形态”。前者由高压缩比视频 VAE 与低 bit latent 共同决定：用更高压缩比的 VAE 把 latent 的通道数与时空维度进一步压下去，再把 latent 以 FP8 或更低 bit 缓存与传输，直接缩小第一式里的分子。后者由分块流式卷积与重叠帧融合决定：解码器不再一次性吃下整段 latent，而是按时间块流式读取、按空间 tile 分块解码，把大块访存拆成可与计算重叠的小块，把第二式从带宽项推向算力项。两者叠加，才同时改善首帧时延、帧间隔稳定性与可驻留 batch。注意这里的因果链是显存→batch→吞吐，以及带宽→帧间隔→SLO，而不是笼统的“变快”。</p>\n<p>量化这一步的具体机制是按通道分组做低 bit 量化并带 per-group scale：</p>\n<div class=\"formula\">$$\\hat{x}=\\text{clip}\\left(\\text{round}\\left(\\frac{x}{s_g}\\right),q_{\\min},q_{\\max}\\right)\\cdot s_g,\\quad s_g=\\frac{\\max_{i\\in g}|x_i|}{q_{\\max}}$$</div>\n<p>分组的意义在于 latent 通道间的动态范围差异大，单一全局 scale 会把小动态范围通道压成零台阶；按通道分组后每组独立定标，量化误差被局部化。量化后的 latent 写入 latent 缓存，缓存按块或按帧滚动回收，这是把第一式的 $b_{\\text{latent}}$ 降下来的直接手段。代价也随之而来：低 bit 量化在纹理与文字区域引入模糊，残差 $x-\\hat{x}$ 必须在解码首层补偿，否则误差会沿上采样逐级放大。工程判断上，这一步的收益是显存与传输量下降带来的 batch 与首帧改善，代价是重建保真度的可接受损失——这正是适用边界的由来。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-3\">三 · 它不解决什么：三条明确的边界</h3>\n<p>第一，它不解决采样端的显存与时延。分块重叠与序列并行针对的是 DiT 采样阶段的激活与注意力开销，本算法只动解码端；采样侧若仍是瓶颈，压缩 latent 不会让采样变快。第二，它不解决高压缩比 VAE 自身的重建保真度上限。压缩比越高，细节损失越大；低 bit latent 在文字与高频纹理上尤其明显，残差首层补偿不足时输出出现模糊与振铃，且无法通过后处理完全恢复。这是规模上限，不是调参能绕过的。第三，它不解决 tile 与 halo 比例决定的重复计算开销上限。空间上采样按 tile 分块解码，tile 间 halo 重叠用于避免接缝；halo 小于卷积感受野时边界出现接缝或亮度跳变，而 tile 越小，重叠重复计算占比越高、吞吐下降。也就是说，分块流式解码的吞吐收益有一个由 halo 比例封顶的天花板。</p>\n<p>还有一条执行层的边界：异步拷贝与 FP8 卷积的重叠若同步点设置不当，SMEM 读写竞争会拖慢解码而非加速。这不是算法边界而是实现边界，但它决定了“从带宽受限推向计算受限”能否真正兑现。把这些边界合起来看，适用场景被刻画得很窄：高分辨率长视频、解码占端到端时延大头、可接受轻微纹理损失。收益随分辨率与时长增大而增大；文字与高频纹理场景需谨慎。反过来说，短视频、低分辨率、或采样侧本就占主导的负载，投入这套机制的边际收益不足以覆盖其复杂度与保真度代价。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-4\">四 · 一个具体例子：从整帧解码到流式分块</h3>\n<p>设想一路高分辨率长视频请求，按旧路径整帧一次性解码：latent 全量驻留，解码器一次读入全部通道与时空维度，HBM 带宽被打满，首帧要等整段解码完成才输出，帧间隔由最慢的那次大访存决定。按本算法的数据流改造后，路径变成五步。第一步，采样输出的 latent 按通道分组量化为 FP8 或低 bit 并加 per-group scale，写入 latent 缓存，缓存体积按第一式缩小。第二步，解码器按时间块流式读取 latent，异步拷贝到 SMEM 并与 FP8 卷积计算重叠，把第二式的带宽项藏到算力项后面。第三步，时间上采样层用重叠帧上下文做融合，消除块边界闪烁。第四步，空间上采样按 tile 分块解码，tile 间 halo 重叠避免接缝。第五步，解码像素按帧流式输出，低 bit 反量化残差在解码首层补偿。</p>\n<p>这个例子里，首帧时延的改善来自两处：latent 缓存变小使首批数据更快就位，流式解码使首帧不必等待整段完成。帧间隔的稳定性来自异步拷贝与 FP8 卷积的重叠——只要同步点正确，单帧时延不再由一次大访存尖峰决定。代价同样可见：halo 重叠带来重复计算，tile 越小这部分占比越高；低 bit latent 在纹理区域需要残差补偿兜底。若把这套机制用在文字密集的视频上，重建损失会先于性能收益暴露出来，这就是边界先于收益生效的典型情形。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-5\">五 · 与相邻机制的切分：为什么必须是解码端</h3>\n<p>把本算法与相邻条目切开，是为了避免在错误的层做优化。分块重叠与序列并行聚焦采样端的显存与时延，它们压缩的是 DiT 主干的激活与通信；本算法聚焦解码端的 latent 压缩与分块流式解码，压缩的是 latent 缓存与解码访存。与常规 FP16 VAE 解码相比，差别不在“更快的卷积”，而在两件事：用低 bit latent 与 FP8 卷积把解码从带宽受限推向计算受限，以及用 halo 重叠的分块解码替代整帧一次性解码。前者改变第二式中 max 的取值方向，后者改变单帧时延的构成。这也解释了为什么在事故现场加卡无效：加卡提升的是 TC 项，而瓶颈在 BW 项；只有把字节数降下来、把访存与计算重叠起来，max 才会翻转。</p>\n<p>支撑这条机制线的是两份材料：paper-dc-videogen-efficient-video-generati-2025 对应高效视频生成与压缩 VAE，paper-fast-and-memory-efficient-video-diff-2024 对应快速且显存高效的视频扩散，前者支撑高压缩 VAE 这条线，后者支撑低 bit latent 解码这条线。两条线必须同时成立：只压 latent 不压解码执行形态，带宽项仍是瓶颈；只改解码执行形态不压 latent，显存与传输量仍卡住 batch。这是本算法作为“组合机制”而非单点技巧的根本原因，也是判断一个负载是否落在适用边界内的操作性标准——先看解码是否占端到端时延大头，再看 latent 缓存是否卡住 batch，两者同时为真，投入才有回报。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-6\">六 · 边界先于收益：解码端压缩能救什么、救不了什么</h3>\n<p>这套方案瞄准的是一类非常具体的线上形态：高分辨率、长时长、按帧流式输出的视频生成服务。它的失效往往不是模型算错，而是服务在长视频请求上塌掉。典型事故形态是：采样阶段一切正常，但请求进入 VAE 解码后，单帧解码时间随分辨率与时长上升，latent 缓存与解码工作区把显存吃满，批大小被迫降到 1，首帧时延超出 SLO，后续帧间隔抖动，前端播放器出现卡顿与重连。根因在于解码卷积与注意力访存密集，端到端时延的大头从采样搬到了解码，而 latent 通道多、传输与缓存占用高，进一步压缩了可驻留的 batch 与流式输出的首帧速度。此时把采样端优化到极致也无济于事——瓶颈在解码器的 HBM 读写与 latent 驻留，而不是采样算力。</p>\n<p>要判断这套方案是否落在适用边界内，先看两个量。latent 缓存占用近似为</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{latent}}\\approx \\frac{C'\\,H'\\,W'\\,T}{\\text{compression}}\\cdot b_{\\text{latent}},\\quad T_{\\text{decode}}\\approx \\max\\left(\\frac{\\text{FLOPs}_{\\text{VAE}}}{\\text{TC}_{\\text{FP8}}},\\ \\frac{\\text{Bytes}_{\\text{latent}}}{\\text{BW}}\\right)$$</div>\n<p>前者说明压缩比与 $b_{\\text{latent}}$ 直接决定能驻留多长的视频与多大的 batch；后者说明解码时延由计算与带宽两个上限中较大者决定。方案的全部收益都建立在“原本是带宽受限”这一前提上：低 bit latent 与 FP8 卷积把 $\\text{Bytes}_{\\text{latent}}$ 压下去，异步拷贝与计算重叠把解码推向计算受限，帧间隔才稳定。若某档硬件上 FP8 卷积吞吐不足、$\\text{FLOPs}_{\\text{VAE}}/\\text{TC}_{\\text{FP8}}$ 反而成为更大项，压缩 latent 只减少显存、不减少时延，收益就从延迟转移到 batch 容量上——这是工程上必须提前算清的账，而不是部署后再发现。</p>\n<p>它明确不解决的问题有三类。其一是重建保真度：高压缩比 VAE 本身损失细节，低 bit latent 在纹理与文字区域进一步模糊，分组量化 $\\hat{x}=\\text{clip}(\\text{round}(x/s_g),q_{\\min},q_{\\max})\\cdot s_g$ 的残差 $x-\\hat{x}$ 只在解码首层补偿，补偿不足时输出出现模糊与振铃，且无法靠后处理完全恢复；文字、字幕、UI 截图类内容属于高风险场景，不应套用同一压缩档。其二是接缝与闪烁：空间 tile 的 halo 重叠小于卷积感受野时，tile 边界出现接缝或亮度跳变；时间上采样层未用重叠帧上下文融合时，块边界闪烁。其三是同步点设置不当造成的反效果：异步拷贝与 FP8 卷积重叠若同步点错位，SMEM 读写竞争会拖慢解码而非加速。此外，tile 越小 halo 重复计算占比越高、吞吐下降，这是压缩收益的直接对冲项。与采样端的分块重叠、序列并行不同，这里动的是解码端的 latent 表示与分块流式结构；与常规 FP16 VAE 解码相比，它用 halo 重叠替代整帧一次性解码，代价是重复计算换显存与首帧。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>方案有效</th><th>方案失效或收益反转</th></tr></thead><tbody><tr><td>负载形态</td><td>高分辨率长视频、解码占端到端时延大头</td><td>短视频、低分辨率，解码占比小</td></tr><tr><td>瓶颈位置</td><td>latent 带宽与显存受限</td><td>FP8 卷积算力不足，转为计算受限</td></tr><tr><td>内容类型</td><td>可接受轻微纹理损失</td><td>文字、高频纹理，残差补偿不足</td></tr><tr><td>分块参数</td><td>halo 不小于卷积感受野</td><td>tile 过小，重叠重复计算占比过高</td></tr></tbody></table>\n<p>规模上限由高压缩比 VAE 的重建保真度与低 bit 量化误差共同决定，而不是由显存容量决定；换言之，加卡不能突破这条边界，只能把 batch 与时长往上顶。工程判断应落在两处：一是按内容类型分档选择压缩比与 latent 位宽，对文字与高频纹理场景保留更高保真通路；二是把 tile 尺寸与 halo 比例作为显式容量参数纳入容量规划，用重复计算开销上限反推可承诺的帧间隔 SLO，而不是等线上出现接缝再回退整帧解码。</p>\n<h3 id=\"alg-vae-decode-2bit-latent-sec-7\">七 · 量化写入 latent 缓存：分组、scale 与残差留存</h3>\n<p>解码链路的第一个动作发生在采样器交出 latent 之后、VAE 尚未启动之前。此时 latent 张量形状为 $C'\\times H'\\times W'\\times T$，通道维 $C'$ 在深度压缩 VAE 下往往被压到远小于常规 VAE 的水平，但时空维 $T$ 随视频时长线性增长，因此缓存的绝对占用仍由 $H'W'T$ 主导。写入步骤按通道分组做低 bit 量化：把 $C'$ 切成若干组 $g$，每组独立求 scale，再量化到 FP8 或更低 bit。分组的意义在于 latent 通道间动态范围差异极大——少数通道承载亮度与低频结构，幅度接近满量程，另一些通道只承载高频残差，幅度小一两个数量级；若用整张量单一 scale，小幅度通道会被量化噪声淹没。</p>\n<div class=\"formula\">$$\\hat{x}=\\text{clip}\\left(\\text{round}\\left(\\frac{x}{s_g}\\right),q_{\\min},q_{\\max}\\right)\\cdot s_g,\\quad s_g=\\frac{\\max_{i\\in g}|x_i|}{q_{\\max}}$$</div>\n<p>这一步的输入是 FP16/BF16 latent，输出是低 bit latent 加每组的 scale（scale 本身以 FP16 或 FP32 存放，体量相对 latent 可忽略）。代价分两块：一是量化本身的访存，读一遍写一遍，按 $\\text{Bytes}_{\\text{latent}}$ 计；二是残差留存——量化误差 $x-\\hat{x}$ 若直接丢弃，纹理与文字区域在解码后无法恢复，因此实现上把残差以低 bit 或稀疏形式另存一份，供解码首层补偿。残差留存使 latent 缓存的实际占用高于纯量化后的理论值，这是压缩比兑现时必须计入的折扣。举例：一段长视频若 latent 缓存按帧滚动回收，量化写入的带宽开销与后续解码读取同量级，因此这一步不能省成“顺手做”，它决定了缓存能否容纳更大 batch。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-8\">八 · 时间块流式读取与异步拷贝重叠</h3>\n<p>VAE 解码器不整段读 latent，而是按时间块推进：一次取若干帧的 latent，异步拷贝到 SMEM，同时让上一块的 FP8 卷积继续在 tensor core 上跑。Blackwell 上的关键是把 HBM 读与计算放进两条流水，用 cp.async 一类机制把拷贝延迟藏在卷积之后。这一步的输入是低 bit latent 块加 scale，输出是块级解码特征图。代价由下式给出上界：</p>\n<div class=\"formula\">$$T_{\\text{decode}}\\approx \\max\\left(\\frac{\\text{FLOPs}_{\\text{VAE}}}{\\text{TC}_{\\text{FP8}}},\\ \\frac{\\text{Bytes}_{\\text{latent}}}{\\text{BW}}\\right)$$</div>\n<p>在 FP16 latent 加 FP16 卷积的常规配置下，第二项通常压过第一项，解码是带宽受限的；换成低 bit latent 加 FP8 卷积后，$\\text{Bytes}_{\\text{latent}}$ 下降、$\\text{TC}_{\\text{FP8}}$ 上升，两项趋于平衡，解码被推向计算受限。这正是帧间隔更稳定的来源：带宽受限时帧间隔受 HBM 争用与缓存抖动影响大，计算受限时它由确定的卷积工作量决定。工程代价在于同步点设置——若异步拷贝的等待点放在卷积之前而非之后，SMEM 读写竞争会让两条流水互相拖慢，解码反而变慢。时间块大小是另一个旋钮：块太小则每块的启动与同步开销占比升高，块太大则 SMEM 放不下、流水深度不足。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-9\">九 · 时间上采样：重叠帧上下文融合</h3>\n<p>时间上采样层把块级特征在时间轴上插值到目标帧率。若各块独立上采样再拼接，块边界两侧的帧缺少对方的上下文，运动补偿不一致，输出出现周期性闪烁。机制上让相邻时间块在上采样时携带重叠帧：第 $k$ 块读取第 $k-1$ 块末尾若干帧的特征作为上下文，融合后再输出本块新增帧。输入是块级特征与重叠上下文，输出是时间维度已扩展的特征序列。代价是重叠帧被重复计算，重复比例约为重叠帧数除以块帧数；块越短，这部分开销占比越高。对长视频流式解码而言，这一层的显存代价可控——重叠上下文只需保留少量帧的特征，不需要回看整段视频，因此它不与“长视频流式分块重叠”那类采样端策略争夺同一块显存。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-10\">十 · 空间 tile 分块解码与 halo 重叠</h3>\n<p>空间上采样把特征图放大到像素分辨率，是 VAE 解码中 FLOPs 与访存最密集的一段。整帧一次性解码在高分辨率下工作区显存吃紧，因此按 tile 切分：每个 tile 独立跑卷积与上采样，tile 之间保留 halo 重叠区。halo 的宽度不得小于该层卷积的感受野，否则 tile 边界处卷积看不到邻域像素，输出出现接缝或亮度跳变。输入是时间上采样后的特征 tile 加 halo 区，输出是像素 tile，边界处裁掉 halo 后拼接。</p>\n<p>代价结构很直接：设 tile 边长 $t$、halo 宽 $h$，重复计算比例约为 $1-(t/(t+2h))^2$。$t$ 越小，这个比例越接近 1，吞吐按比例下降；$t$ 越大，单 tile 工作区显存越高，可能超出 SMEM 与寄存器的承载。工程判断是让 $t$ 取到工作区显存允许的上限，把 halo 开销压到可接受区间，而不是为了省显存把 tile 切碎。这一步的另一个代价是 halo 区的 latent 需要被重复读取，与异步拷贝流水叠加时要注意不要让 halo 读放大抵消低 bit latent 带来的带宽收益。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-11\">十一 · 首层残差补偿与按帧流式输出</h3>\n<p>解码首层在反量化低 bit latent 的同时加回第一步留存的残差：$\\tilde{x}=\\hat{x}+r$，其中 $r$ 是量化残差。这一步的位置很关键——若把残差补偿放在解码末端，卷积已经把量化误差放大并混入邻域，补偿只能修正全局亮度而无法恢复纹理；放在首层则让后续卷积在接近原始 latent 的输入上工作，高频细节得以保留。输入是低 bit latent、scale 与残差，输出是首层特征。代价是首层要多读一份残差、多做一次加法，访存增量取决于残差的存放精度；若残差也压到低 bit，补偿效果打折，文字与高频纹理区域仍会模糊与振铃，且后处理无法完全恢复。</p>\n<p>最后一步把像素按帧流式输出：每解出一帧就交给下游消费或写入，而不是等整段视频解码完再统一输出。这直接决定首帧时延——首帧只需第一组时间块走完量化反解、时间上采样、空间 tile 解码与残差补偿，不必等待全长视频。代价是输出侧的缓冲管理：帧间隔由最慢的那一级决定，若空间 tile 解码的 halo 开销或时间上采样的重叠计算在某一帧上偏重，帧间隔会出现抖动。因此部署上把 VAE 解码按帧做数据并行、与采样阶段的序列并行轴分离，让解码的流水节奏不被采样侧的长序列通信打断；latent 缓存按块或按帧滚动回收，使驻留量不随时长增长。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-12\">十二 · 步骤间的耦合与失败模式定位</h3>\n<p>五个步骤不是独立优化，而是共享同一组预算。分组量化的组数决定 scale 的访存量与残差体量；时间块大小决定异步拷贝的流水深度与时间上采样的重叠比例；tile 与 halo 比例决定空间解码的重复计算上限；残差精度决定首层补偿能否兑现高压缩比 VAE 的保真度承诺。任何一处调紧，都会把代价推到相邻步骤。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入 → 输出</th><th>主要代价</th><th>失败模式</th></tr></thead><tbody><tr><td>分组量化写入</td><td>FP16 latent → 低 bit latent + scale + 残差</td><td>读写带宽、残差额外占用</td><td>组过粗导致小幅度通道被噪声淹没</td></tr><tr><td>时间块流式读取</td><td>低 bit latent 块 → 块级特征</td><td>HBM 带宽与 SMEM 竞争</td><td>同步点错位，异步拷贝拖慢卷积</td></tr><tr><td>时间上采样</td><td>块级特征 + 重叠上下文 → 扩展特征</td><td>重叠帧重复计算</td><td>无重叠上下文，块边界闪烁</td></tr><tr><td>空间 tile 解码</td><td>特征 tile + halo → 像素 tile</td><td>halo 重复计算与重复读取</td><td>halo 小于感受野，接缝与亮度跳变</td></tr><tr><td>残差补偿与输出</td><td>低 bit latent + 残差 → 首层特征 → 帧</td><td>残差访存、输出缓冲</td><td>补偿不足，纹理模糊与振铃不可恢复</td></tr></tbody></table>\n<p>定位失败模式时按数据流顺序排查最有效：先看量化组是否与 latent 通道动态范围匹配，再看异步拷贝的等待点是否落在卷积之后，再看时间上采样是否真的带上了前块上下文，最后量 halo 宽度与卷积感受野的关系。若输出整体偏亮或偏暗而非局部接缝，问题在残差补偿的位置或精度；若帧间隔抖动而非首帧慢，问题多在空间 tile 的 halo 比例与输出缓冲策略上。这套顺序把“解码变慢”或“画质变差”的模糊症状映射到具体步骤的具体参数，避免在整条链路上盲目调参。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-13\">十三 · 解码数据流上的四道关卡：量化写缓存、异步卷积、重叠融合与 halo 分块</h3>\n<p>按请求生命周期拆解，第一道关卡发生在采样输出落盘之前：latent 张量按通道分组量化并写入 latent 缓存。分组量化写作 <span class=\"formula\">$$\\hat{x}=\\text{clip}\\left(\\text{round}\\left(\\frac{x}{s_g}\\right),q_{\\min},q_{\\max}\\right)\\cdot s_g,\\quad s_g=\\frac{\\max_{i\\in g}|x_i|}{q_{\\max}}$$</span>，其中 $g$ 为通道分组、$s_g$ 为该组 scale。分组的意义在于 latent 通道间动态范围差异大，单一全局 scale 会把小幅度通道压成零。这一步的输入是采样器输出的高精度 latent，输出是带 per-group scale 的低 bit latent 缓存；代价是缓存占用从 <span class=\"formula\">$$\\text{Mem}_{\\text{latent}}\\approx \\frac{C'\\,H'\\,W'\\,T}{\\text{compression}}\\cdot b_{\\text{latent}}$$</span> 中的 $b_{\\text{latent}}$ 直接下降，使更长视频或更大 batch 得以驻留，但反量化残差 $x-\\hat{x}$ 被推迟到解码首层补偿——这是本方案最脆弱的一环，补偿不足时纹理与文字区域出现模糊与振铃，后处理无法恢复。缓存按块或按帧滚动回收，批大小实际由 latent 缓存加解码工作区显存共同约束，而非单看权重。</p>\n<p>第二道关卡是解码器按时间块流式读取 latent：异步拷贝把 latent 块搬入 SMEM，与 FP8 卷积计算重叠。这一步把解码的瓶颈从 HBM 带宽推向张量核算力，帧间隔由 <span class=\"formula\">$$T_{\\text{decode}}\\approx \\max\\left(\\frac{\\text{FLOPs}_{\\text{VAE}}}{\\text{TC}_{\\text{FP8}}},\\ \\frac{\\text{Bytes}_{\\text{latent}}}{\\text{BW}}\\right)$$</span> 决定，低 bit latent 缩小分子中的 Bytes 项，FP8 卷积抬高分母中的算力项，两者共同把 max 推向计算侧，帧间隔更稳定。失效条件是同步点设置不当：若拷贝完成与卷积启动之间的屏障过粗，SMEM 读写竞争会拖慢解码而非加速，此时异步反而成为负收益。工程判断是让拷贝粒度与时间块对齐，块过小则同步开销占比上升，块过大则首帧等待变长。</p>\n<p>第三、四道关卡是时间上采样与空间上采样。时间层必须用重叠帧上下文做融合，否则块边界出现闪烁；空间层按 tile 分块解码，tile 间 halo 重叠不得小于卷积感受野，否则边界出现接缝或亮度跳变。halo 带来的重复计算占比随 tile 缩小而上升，直接吃掉吞吐：设 tile 边长 $t$、halo 宽度 $h$，重复计算比例约为 <span class=\"formula\">$$\\eta\\approx \\frac{(t+2h)^2-t^2}{t^2}$$</span>，$t$ 越小 $\\eta$ 越大。下表给出各步骤的输入、输出与主要代价。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>分组量化写缓存</td><td>高精度 latent</td><td>低 bit latent + scale</td><td>残差损失、首层补偿压力</td></tr><tr><td>异步拷贝 + FP8 卷积</td><td>latent 时间块</td><td>块级解码特征</td><td>SMEM 竞争、同步开销</td></tr><tr><td>时间重叠融合</td><td>相邻块特征</td><td>无闪烁帧序列</td><td>额外帧上下文显存</td></tr><tr><td>空间 tile + halo</td><td>单帧特征</td><td>像素 tile</td><td>重复计算 $\\eta$、吞吐下降</td></tr><tr><td>流式输出 + 首层残差补偿</td><td>像素 tile、残差</td><td>逐帧像素</td><td>首帧时延、补偿算力</td></tr></tbody></table>\n<p>适用边界由此清晰：高分辨率长视频且 VAE 解码占端到端时延大头、可接受轻微纹理损失时收益随分辨率与时长增大；文字与高频纹理场景是规模上限所在，由高压缩比 VAE 的重建保真度与低 bit 量化误差共同决定。并行拓扑上 VAE 解码按帧做数据并行，与采样阶段的序列并行轴分离，两者不可混用同一通信域。首帧时延由第一个时间块加首个 tile 的 halo 填充决定，SLO 以首帧时延与帧间隔为主，故块大小与 tile 大小的选择本质是在首帧等待、重复计算与 SMEM 竞争三者间取平衡。</p>\n<h3 id=\"alg-vae-decode-2bit-latent-sec-14\">十四 · 分组量化：从连续 latent 到可缓存整数</h3>\n<p>低 bit latent 的第一步不是“压”，而是“可逆地压”。采样器吐出的 latent 张量形状为 $C'\\times T\\times H'\\times W'$，通道间动态范围差异极大——少数通道承载高频纹理，幅值接近满量程，另一些通道近似直流分量，幅值低一到两个数量级。若用单一全局 scale，低幅通道会被量化到零附近，解码端再也拿不回来。因此按通道分组，每组独立求 scale：</p>\n<div class=\"formula\">$$\\hat{x}=\\text{clip}\\left(\\text{round}\\left(\\frac{x}{s_g}\\right),q_{\\min},q_{\\max}\\right)\\cdot s_g,\\quad s_g=\\frac{\\max_{i\\in g}|x_i|}{q_{\\max}}$$</div>\n<p>推导的关键一步在 $s_g$ 的取法：用组内绝对最大值对齐量化上界 $q_{\\max}$，等价于最小化该组的最大绝对误差（minimax），而不是最小化均方误差。这一步选择决定了低 bit 下的行为——minimax 保证没有元素溢出饱和区，代价是幅值小的元素分到的有效位数偏少。对 FP8（E4M3）而言 $q_{\\max}$ 由指数位决定，尾数只有 3 位，组内动态范围一旦超过约两个数量级，小幅值元素就退化为粗粒度台阶。这就是为什么分组要沿通道切而不是沿空间切：空间邻域内幅值连续，分组收益低；通道间统计独立，分组才能把动态范围“拉平”。</p>\n<p>工程代价直接落在两处。其一是 scale 的元数据开销：每组一个 FP32 scale，若组大小为 32 通道，则每 32 个低 bit 元素附带 4 字节，等效位宽上升；组越小精度越好但元数据占比越高，组大小是精度与带宽的折中旋钮。其二是反量化的算力位置：残差 $x-\\hat{x}$ 不在缓存里存，而是在解码首层用 $\\hat{x}$ 与原始高精度首层权重的组合补偿，把量化误差的吸收放在计算最便宜的地方，避免为残差单独开一条高精度通路。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-15\">十五 · 解码时延的双约束：算力与带宽取大</h3>\n<p>VAE 解码在 Blackwell 上的时延不是单一瓶颈，而是两条流水线的较大者：</p>\n<div class=\"formula\">$$T_{\\text{decode}}\\approx \\max\\left(\\frac{\\text{FLOPs}_{\\text{VAE}}}{\\text{TC}_{\\text{FP8}}},\\ \\frac{\\text{Bytes}_{\\text{latent}}}{\\text{BW}}\\right)$$</div>\n<p>这个 max 的形式本身就是结论：当 latent 以 FP16 缓存时，第二项通常压过第一项，解码是带宽受限的——SM 在等 HBM 把 latent 搬进来，FP8 张量核空转。把 latent 压到 FP8 或更低 bit，$\\text{Bytes}_{\\text{latent}}$ 按位宽比例下降，第二项随之下降，直到与第一项交叉，解码转为计算受限。交叉点的位置由压缩比与位宽共同决定：高压缩比 VAE 已经把 $C'H'W'T$ 压小，再叠加低 bit，带宽项下降是乘性的，而 FLOPs 项基本不变（卷积的乘加次数由输出分辨率与通道数决定，与 latent 位宽无关）。</p>\n<p>推导的关键一步是把“访存”拆成 latent 读取与解码工作区读写两部分，前者随位宽线性缩小，后者（中间特征图、halo 缓冲）不随 latent 位宽缩小，因此低 bit 化的边际收益递减：当 latent 字节数降到与工作区同量级，继续压 latent 对总带宽的贡献趋缓。这解释了为什么分块流式解码必须与低 bit 同时上——分块把工作区限制在 tile 加 halo 的规模，使工作区字节数可控，低 bit 才能真正把 max 的第一项顶上来。</p>\n<p>具体例子：一段高分辨率长视频，latent 通道多、时间维长，FP16 缓存下解码器每读一个时间块的 latent 就要等一次 HBM 往返，帧间隔被带宽钉死；改为 FP8 分组量化后，同一时间块的字节数减半，异步拷贝把这段读取藏进上一块的 FP8 卷积里，帧间隔由卷积算力决定而变得平稳。这正是“从带宽受限推向计算受限”的物理含义。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-16\">十六 · 伪代码：量化写入与流式解码主循环</h3>\n<p>下面给出可直接落地的两段伪代码思路，重点在同步点与缓冲生命周期，而非具体 API。</p>\n<p>量化写入端：按通道分组遍历 latent，求组内绝对最大值得到 $s_g$，做 round-clip 后写低 bit 缓存，同时把 $s_g$ 写入与 latent 块同生命周期的 scale 表。关键实现细节是分组遍历要与后续解码的读取顺序一致——解码按时间块、按通道组读，量化就按同样的块边界切分，使一个时间块的 scale 表能连续取出，避免解码时做跨块 gather。</p>\n<p>解码主循环：对每个时间块 $t$，发起异步拷贝把该块 latent 与 scale 搬入 SMEM（双缓冲，块 $t+1$ 的拷贝与块 $t$ 的计算重叠）；在 SMEM 上做反量化得到 FP8 激活，进 FP8 卷积；时间上采样层取块 $t-1$、$t$、$t+1$ 的重叠帧上下文做融合；空间上按 tile 展开，每个 tile 带 halo 读取邻域；输出帧流式写出，同时把已消费的 latent 块滚动回收。同步点只设在“拷贝完成”与“卷积消费完 SMEM”之间，用双缓冲把这两件事错开一个块，若同步点设得过密，SMEM 读写竞争会让重叠失效，解码反而变慢——这是材料里点明的失败模式。</p>\n<p>代价核算：双缓冲使 SMEM 占用翻倍，tile 加 halo 使每个 tile 的卷积 FLOPs 按 $(1+\\text{halo}/\\text{tile})$ 的平方量级放大（二维 tile 两个方向都带 halo）。tile 越小，halo 占比越高，重复计算吃掉低 bit 带来的吞吐收益；tile 越大，工作区显存越大，batch 上限被压低。tile 尺寸因此是显存、吞吐与接缝质量的三方折中。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-17\">十七 · 显存账：latent 缓存与 batch 上限</h3>\n<p>latent 缓存占用可写成：</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{latent}}\\approx \\frac{C'\\,H'\\,W'\\,T}{\\text{compression}}\\cdot b_{\\text{latent}}$$</div>\n<p>逐项看：$C'H'W'T$ 是未压缩 latent 的元素数，$\\text{compression}$ 是高压缩比 VAE 带来的通道与时空维度的联合压缩因子，$b_{\\text{latent}}$ 是每元素位宽。三项相乘决定了一段视频在缓存里占多少字节。推导的关键一步是把压缩因子与位宽视为两个独立可调的乘性因子：提高压缩比降低元素数，降低位宽降低每元素成本，两者叠加使缓存占用按乘积下降。这正是“更长视频或更大 batch 可驻留”的来源——batch 上限大致由可用显存除以单请求缓存加解码工作区得到，缓存项按乘积缩小后，分母变小，能塞进的请求数上升。</p>\n<p>但工作区不随位宽缩小。解码器在任意时刻需要持有当前 tile 的输入特征、若干中间层输出与 halo 缓冲，这部分字节数由 tile 尺寸与通道宽度决定，与 latent 位宽无关。因此 batch 上限的实际表达式是“可用显存 ÷（单请求 latent 缓存 + 单请求解码工作区）”，低 bit 只压第一项。当第一项被压到与第二项同量级，继续降位宽的边际收益消失，此时提升 batch 要靠缩小 tile 或复用工作区，而缩小 tile 又触发 halo 重复计算——三个约束互相咬合。</p>\n<p>具体判断：若某配置下 latent 缓存占单请求显存的大头，低 bit 化能显著抬 batch；若工作区已占大头，应先调 tile 与分块策略，再谈位宽。这个次序判断比盲目降 bit 更能改善吞吐。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-18\">十八 · 误差传播：残差补偿与接缝、闪烁的耦合</h3>\n<p>低 bit 量化误差不会均匀分布。纹理与文字区域 latent 幅值高、空间频率高，分组量化后组内小幅值元素被粗台阶化，解码首层若补偿不足，输出表现为模糊与振铃，且后处理无法完全恢复——材料明确这是失败模式。补偿的机制是在解码首层用 $\\hat{x}$ 与高精度首层权重联合计算，把量化误差折算进特征而非直接进像素，使后续层有机会用上下文平滑掉。补偿强度与首层通道宽度相关：首层越宽，误差被摊薄得越好，但首层 FLOPs 也越高。</p>\n<p>接缝与闪烁是另一类误差，来源不是量化而是分块。空间 tile 的 halo 若小于卷积感受野，边界处感受野被截断，出现接缝或亮度跳变；时间上采样层若不用重叠帧上下文，块边界出现闪烁。这两类误差与量化误差在视觉上会叠加：低 bit 使边界两侧的 latent 反量化结果本就有细微差异，halo 不足又放大了这个差异，接缝更明显。因此 halo 的下界应由卷积感受野决定，而不是由 tile 尺寸的比例决定；时间维的重叠帧数同理，至少覆盖时间上采样核的感受野。</p>\n<p>代价上，halo 与重叠帧都是纯重复计算：halo 每扩一圈，tile 的有效计算占比下降；重叠帧每多一帧，时间块的卷积量上升。稳定性技巧里“halo 不少于感受野”是一条硬约束，突破它换来的吞吐会被接缝后处理或重解码吃掉，净收益为负。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-19\">十九 · 与采样端并行轴的分离及规模上限</h3>\n<p>VAE 解码按帧做数据并行，与采样阶段的序列并行轴分离——这是部署配方里的关键结构判断。采样端的序列并行沿 token 或帧序列切分，通信发生在注意力层；解码端按帧切分后，每帧的解码只依赖自身 latent 块与相邻重叠帧，跨卡通信仅发生在 halo 交换上，通信量远小于采样端。两条并行轴分离的好处是：解码可以独立扩卡而不扰动采样拓扑，解码卡的显存配置也可以与采样卡不同（解码更吃工作区，采样更吃 KV 与权重）。</p>\n<p>规模上限由两个因素封顶。其一是高压缩比 VAE 的重建保真度：压缩比越高，latent 承载的信息越少，低 bit 再削一层，文字与高频纹理场景的重建损失不可逆，这是适用边界而非调参能解决的问题。其二是 tile 与 halo 的比例：重复计算开销的上限由 halo 占 tile 的比例决定，tile 越小上限越低。两者共同决定“分辨率与时长增大时收益递增，但到某一规模后收益被保真度与重复计算抵消”的形状。</p>\n<p>工程判断落在具体机制上：先按感受野定 halo 下界，再按显存定 tile 上界，两者夹出的区间就是可用的 tile 范围；在这个区间内选最大 tile 以压低重复计算，同时用双缓冲异步拷贝把 latent 读取藏进 FP8 卷积，使 $T_{\\text{decode}}$ 的 max 落在算力项上。若实测帧间隔仍随分辨率线性上升而非平稳，说明带宽项仍在主导，此时应检查 scale 表是否连续取出、SMEM 双缓冲是否真正错开一个块，而不是继续降位宽。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-20\">二十 · 失效边界：量化误差、halo 比例与同步点的三重约束</h3>\n<p>这套方案的收益并非无条件成立，其边界由三个量共同决定：量化步长、halo 与 tile 的比例、以及异步拷贝与 FP8 卷积的同步点。分组量化写成 <span class=\"formula\">$$\\hat{x}=\\text{clip}\\left(\\text{round}\\left(\\frac{x}{s_g}\\right),q_{\\min},q_{\\max}\\right)\\cdot s_g,\\quad s_g=\\frac{\\max_{i\\in g}|x_i|}{q_{\\max}}$$</span> 时，误差上界由组内动态范围决定：若某组通道同时含低频平坦区与高频文字笔画，$s_g$ 被最大值拉大，小幅值纹理被压到同一量化格，残差 $x-\\hat{x}$ 在解码首层补偿也只能恢复首层可见的部分，后续上采样会放大振铃。因此按通道分组而非整张 latent 共享 scale 是必要的，但分组越细，scale 元数据与反量化开销越高，这是精度与带宽的直接交换。</p>\n<p>空间分块的代价可写成重复计算占比 <span class=\"formula\">$$\\rho\\approx\\frac{(t+h)^2-t^2}{t^2}=\\frac{2h}{t}+\\frac{h^2}{t^2}$$</span>，其中 $t$ 为 tile 边长、$h$ 为 halo 宽度。halo 必须不小于该层卷积感受野，否则 tile 边界出现接缝或亮度跳变；而 $t$ 缩小时 $\\rho$ 迅速上升，吞吐下降。工程判断是让 $t$ 取感受野的数倍，使 $\\rho$ 落在个位数百分比，同时把 halo 区域的计算结果丢弃而非写回，避免边界帧被重复融合两次。</p>\n<p>时间维的失效更隐蔽：时间上采样层若不做重叠帧上下文融合，块边界闪烁在单帧检查中不可见，只在连续播放时暴露；而异步拷贝与 FP8 卷积若同步点设置不当，SMEM 读写竞争会让解码比同步执行更慢。可实现的伪代码思路是双缓冲：<ul><li>预取第 $k+1$ 个时间块的 latent 到 SMEM 缓冲 B，同时对缓冲 A 做 FP8 卷积；</li><li>仅在卷积输出写回 HBM 前插入 barrier，读取侧不设全局同步；</li><li>每块解码完成后按帧滚动回收 latent 缓存，释放的显存立即归还给下一 batch。</li></ul>代价体现在显存与延迟的耦合：双缓冲使解码工作区翻倍，低 bit latent 节省的缓存若被工作区吃掉，batch 上限并不会提升；首帧时延则由第一个时间块加 halo 的完整解码链路决定，分块越细首帧越快但总吞吐越差。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>可观测症状</th><th>系统代价</th></tr></thead><tbody><tr><td>组内动态范围过大</td><td>文字与高频纹理模糊、振铃</td><td>残差补偿增加首层访存</td></tr><tr><td>halo 小于感受野</td><td>tile 接缝、亮度跳变</td><td>$\\rho$ 上升，吞吐下降</td></tr><tr><td>同步点过密</td><td>SMEM 竞争，解码变慢</td><td>重叠收益归零</td></tr></tbody></table>\n<p>适用边界因此很明确：高分辨率长视频、解码占端到端时延大头、且可接受轻微纹理损失的场景收益随分辨率与时长增大；文字密集与高频纹理场景应提高 latent bit 宽或缩小分组，用带宽换保真度。规模上限由高压缩比 VAE 的重建保真度与量化误差共同封顶，而非由算力封顶——这正是把解码从带宽受限推向计算受限后必须重新做容量规划的原因。</p>\n<h3 id=\"alg-vae-decode-2bit-latent-sec-21\">二十一 · 请求形态的匹配判据</h3>\n<p>这套负载配方不是给所有视频推理请求准备的。它成立的第一个前提是：请求本身就是高分辨率、长时长、且以流式方式消费的视频生成请求——分辨率越高、时长越长，VAE 解码在端到端时延中的占比越大，收益才越明显。反过来，短片段、低分辨率、或者用户只关心最终整段文件而非首帧到达时间的请求，把 latent 压到 FP8 以下并引入分块流式解码，换来的是额外的量化误差与 halo 重复计算，收益被这些开销吃掉。判断一个请求是否落在配方内，看三个量：单帧像素量、总帧数、以及首帧 SLO 是否显著紧于整段完成时间。三者同时满足，才值得启用低 bit latent 缓存与流式解码链路。</p>\n<p>请求形态还决定了并发模型。流式解码意味着解码器对每个请求维持一个滚动的时间块窗口，而不是一次性把整段 latent 全部展开。这个窗口的大小直接对应解码工作区显存：窗口越长，SMEM 与中间激活占用越大，可并发的请求数越少。因此并发与批大小不是独立可调的旋钮，而是被窗口长度与 latent 缓存共同约束的结果。批大小在这里的作用不是提升解码吞吐的主力——解码是访存与计算混合的流水线，真正的吞吐来自异步拷贝与 FP8 卷积的重叠——而是摊薄每请求固定开销、把 HBM 带宽吃满的手段。</p>\n<p>具体例子：一个请求要求 4K 级分辨率、数百帧、首帧在秒级内可见。此时若按整帧一次性解码，latent 展开后的显存峰值会把并发压到个位数；改用按时间块滚动读取、低 bit latent 驻留缓存后，同一张卡上可同时维持多个请求的滚动窗口，首帧时延由第一个时间块的解码时间决定，而不是整段解码时间。这就是请求形态与配方对齐时的典型形态。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-22\">二十二 · 长度分布对批大小与显存预算的约束</h3>\n<p>长度分布是负载配方里最容易被忽略的变量。latent 缓存占用与解码工作区占用都随时长线性增长，而批大小又必须为最长的那个请求预留空间，否则长请求到达时要么被拒绝、要么触发抢占与重算。工程上的做法是按长度分桶：短请求走大 batch、整段或粗粒度分块解码；长请求走小 batch、细粒度滚动窗口。分桶边界由 latent 缓存预算反推，而不是拍脑袋定。</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{latent}}\\approx \\frac{C'\\,H'\\,W'\\,T}{\\text{compression}}\\cdot b_{\\text{latent}},\\quad T_{\\text{decode}}\\approx \\max\\left(\\frac{\\text{FLOPs}_{\\text{VAE}}}{\\text{TC}_{\\text{FP8}}},\\ \\frac{\\text{Bytes}_{\\text{latent}}}{\\text{BW}}\\right)$$</div>\n<p>第一个式子说明：latent 缓存随帧数 T 线性增长，压缩比与每元素比特数 b_latent 是仅有的两个乘性缩减因子。把 b_latent 从 FP16 降到 FP8 直接把缓存减半，这正是低 bit latent 让更长视频或更大 batch 驻留的机制来源。第二个式子说明解码时间的下界由计算与带宽两条路径的较大者决定；当 b_latent 下降，Bytes_latent 项缩小，解码从带宽受限滑向计算受限，帧间隔变得更可预测——这对 SLO 以帧间隔为主的流式请求是实质性改善。</p>\n<p>代价在长度分布的长尾上暴露得最清楚。若长度分布方差大，按最长请求预留显存会让平均 batch 极小，吞吐塌陷；若按平均长度预留，长请求到达时触发缓存回收与窗口重建，首帧时延出现尖峰。因此配方要求 latent 缓存按块或按帧滚动回收，让显存占用跟随活跃窗口而非总时长，把长尾请求的边际显存成本压到接近常数。具体例子：一批请求时长从数十帧到数百帧不等，滚动回收使长请求只多占一个窗口的显存，而不是整段 latent 的显存，批大小得以按窗口而非按时长确定。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-23\">二十三 · 并发与批大小的实际调节点</h3>\n<p>并发数由三个约束取最小：latent 缓存预算、解码工作区预算、以及 HBM 带宽。前两个是硬约束，第三个是软约束——带宽不够时流水线拉长，帧间隔抖动。调节点不在批大小本身，而在时间块长度与空间 tile 尺寸。时间块越长，单次解码的计算密度越高、异步拷贝与计算重叠的窗口越大，但工作区显存占用越高、首帧时延越长；时间块越短，首帧越快、并发越高，但每块的固定开销占比上升。</p>\n<p>空间 tile 尺寸的调节更微妙。tile 越小，halo 重叠占 tile 面积的比例越高，重复计算开销越大。设 tile 边长为 L、halo 宽度为 h（不小于卷积感受野），则重复计算比例约为 1-(L/(L+2h))² 量级；L 缩小一半，该比例显著上升，吞吐下降。这就是“tile 越小重叠开销占比越高”的定量含义。工程判断是：在满足工作区显存约束的前提下取尽可能大的 tile，让 halo 占比落在可接受区间；只有当单 tile 显存放不下时才缩小 tile，并接受吞吐损失。</p>\n<ul>\n<li>机制：解码器按时间块流式读取 latent，异步拷贝到 SMEM 与 FP8 卷积计算重叠；块间用重叠帧上下文融合。</li>\n<li>公式思路：有效吞吐 ≈ 名义吞吐 × (1 − halo 重复比例)，重复比例随 tile 缩小而上升。</li>\n<li>系统代价：时间块拉长提升计算密度但抬高首帧时延与工作区显存；tile 缩小降低单块显存但抬高重复计算、拉低吞吐。</li>\n<li>例子：同一并发目标下，把时间块从单帧拉到多帧，首帧时延上升而帧间隔更稳；把 tile 从大改小以塞进显存，吞吐按 halo 比例下降。</li>\n</ul>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-24\">二十四 · 负载不对时的失效形态</h3>\n<p>负载与配方错配时，失效不是均匀退化，而是集中在几个可识别的形态上。第一类是请求形态错配：低分辨率短片段走这套链路，低 bit latent 的量化误差在总时延中占比被放大，而流式解码的 halo 开销没有对应的时延收益来抵消，结果是质量下降且吞吐不升。第二类是长度分布错配：按短请求调优的批大小遇到长请求长尾，缓存回收与窗口重建导致首帧时延尖峰，SLO 被击穿。</p>\n<p>第三类是并发过高：latent 缓存与工作区挤占 HBM 带宽，异步拷贝与 FP8 卷积的重叠被同步点打断，SMEM 读写竞争使解码变慢而非变快。这是最隐蔽的失效——表面上流水线还在跑，实际重叠失效，解码退回带宽受限，帧间隔抖动放大。第四类是 tile 与 halo 配置错误：halo 小于卷积感受野时 tile 边界出现接缝或亮度跳变；时间上采样未用重叠帧上下文时块边界闪烁。这两类属于配置性失效，可通过固定 halo 下限与强制重叠帧融合来消除。</p>\n<p>第五类是精度失效：高压缩比 VAE 叠加低 bit latent，在文字与高频纹理区域重建损失明显，残差首层补偿不足时输出模糊与振铃，后处理无法完全恢复。这类失效不可通过调度修复，只能通过提高该区域的比特分配或退回更高精度 latent 来缓解。具体例子：含字幕或细密纹理的视频请求，在低 bit latent 下文字边缘出现振铃，残差补偿只能减轻不能消除，此时配方应判定该请求超出适用边界。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-25\">二十五 · 配方与相邻机制的边界划分</h3>\n<p>这套负载配方的边界要与其他机制划清，否则会在错误的层上调参。分块重叠与序列并行聚焦采样端的显存与时延，本配方聚焦解码端的 latent 压缩与分块流式解码；两者共享“分块”这个词，但作用对象不同——前者切的是采样计算图，后者切的是 VAE 解码的时间与空间维度。与常规 FP16 VAE 解码相比，本配方用低 bit latent 与 FP8 卷积把解码从带宽受限推向计算受限，并用 halo 重叠替代整帧一次性解码；代价是重建保真度与重复计算。</p>\n<p>与 NVFP4 量化推理、FP8 时空注意力内核等条目相比，本配方的量化对象是 latent 缓存与解码卷积，量化粒度是通道分组加 per-group scale，而非注意力权重或激活。分组的意义在于适配 latent 通道间动态范围差异：单通道动态范围大时，全局 scale 会把小值通道压到零，分组 scale 保留各组分辨率。这条机制决定了负载配方中“低 bit latent 可用”的前提——若通道动态范围差异极大且分组过粗，量化误差会在解码首层放大。</p>\n<p>工程判断落在规模上限上：收益随分辨率与时长增大，但上限由高压缩比 VAE 的重建保真度与低 bit 量化误差共同决定。文字与高频纹理场景需谨慎，tile 与 halo 比例决定重复计算开销上限。配方不是无条件加速器，而是一组在特定请求形态、长度分布、并发区间内才成立的参数组合；离开这个区间，失效形态会先于收益出现。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-26\">二十六 · 负载配方：长视频流式解码吃得住，短请求与高并发吃不住</h3>\n<p>这套方案的负载画像非常窄：请求形态必须是<b>高分辨率、长时长、以流式解码交付</b>的视频生成，SLO 由首帧时延与帧间隔共同定义。批大小不取决于采样端算力，而被 latent 缓存与解码工作区显存卡死，可用 <span class=\"formula\">$$\\text{Mem}_{\\text{latent}}\\approx \\frac{C'\\,H'\\,W'\\,T}{\\text{compression}}\\cdot b_{\\text{latent}}$$</span> 粗算：压缩比与 latent 位宽同时下调，才使更长 $T$ 或更大 batch 驻留。反过来，若请求是短片段、低分辨率、或一次性整段返回（非流式），高压缩 VAE 的收益立刻消失——解码不再是端到端大头，而分组量化、halo 重叠、残差补偿这些固定开销照付，单位请求成本反而高于常规 FP16 VAE 解码。这类请求应走整帧解码路径，不要塞进分块流式管线。</p>\n<p>并发维度上，本方案与采样端的序列并行轴分离，VAE 解码按帧做数据并行，因此并发能力由“每路 latent 缓存 + 解码 tile 工作区”决定，而非由 KV 或注意力 workspace 决定（KV 不涉及，latent 缓存按块或按帧滚动回收）。当并发路数上升而单路时长不变时，latent 缓存线性膨胀，最先撞墙的是显存而非算力；此时若强行缩小 tile 换取更多并发，halo 重叠占比上升，重复计算吃掉吞吐。设 tile 边长 $t$、halo 宽度 $h$（须不小于卷积感受野），重叠重复计算比例近似 <span class=\"formula\">$$\\eta\\approx 1-\\left(\\frac{t}{t+2h}\\right)^{2}$$</span>，$t$ 越小 $\\eta$ 越大，帧间隔抖动随之变大，SLO 从“稳定帧间隔”退化为“看运气”。这正是把带宽受限推向计算受限后必须守住的计算预算。</p>\n<p>负载不对时的失效是可预测的。第一类：文字与高频纹理场景配低 bit latent，per-group scale 按通道分组虽能吸收通道间动态范围差异，但组内离群值仍被截断，残差 $x-\\hat{x}$ 在解码首层补偿不足时输出模糊与振铃，后处理无法完全恢复——这是规模上限，由高压缩比 VAE 的重建保真度与量化误差共同决定，不是调参能绕过的。第二类：空间 tile 的 halo 小于卷积感受野，tile 边界出现接缝或亮度跳变；时间上采样未用重叠帧上下文融合，块边界闪烁。第三类最隐蔽：异步拷贝与 FP8 卷积的重叠若同步点设置不当，SMEM 读写竞争会拖慢解码而非加速，表现为 $T_{\\text{decode}}\\approx\\max\\left(\\text{FLOPs}_{\\text{VAE}}/\\text{TC}_{\\text{FP8}},\\ \\text{Bytes}_{\\text{latent}}/\\text{BW}\\right)$ 中本该被隐藏的带宽项重新暴露。工程判断很直接：先按分辨率与时长筛请求，长视频流式才进这条管线；再按纹理敏感度决定 latent 位宽与是否保留残差通路；最后用 halo 比例反推 tile 下限，把重复计算开销锁在吞吐预算内。</p>\n<h3 id=\"alg-vae-decode-2bit-latent-sec-27\">二十七 · 硬件档位：按解码瓶颈选卡，而不是按采样规模选卡</h3>\n<p>部署这套方案时，第一个判断不是“模型多大”，而是“VAE 解码在目标分辨率与时长下是带宽受限还是计算受限”。用公式判断：</p>\n<div class=\"formula\">$$T_{\\text{decode}}\\approx \\max\\left(\\frac{\\text{FLOPs}_{\\text{VAE}}}{\\text{TC}_{\\text{FP8}}},\\ \\frac{\\text{Bytes}_{\\text{latent}}}{\\text{BW}}\\right)$$</div>\n<p>当第二项占优时，加卡不会缩短单请求解码时延，只会抬高总吞吐；此时正确的档位是单卡或单节点少卡、把预算花在 HBM 带宽与 SMEM 容量上。当第一项占优时（FP8 卷积把解码推入计算受限），才值得上多卡做帧级数据并行。工程上的判据是：先在一张卡上跑目标分辨率的最长视频，测量解码阶段 HBM 读带宽是否接近峰值；若接近，说明仍被 latent 读取与激活搬运拖住，先调 tile 与异步拷贝重叠，再考虑加卡。</p>\n<p>Blackwell 档位选择上，B200/B300 单卡适合中等分辨率、batch 受 latent 缓存约束的场景；GB200/GB300 NVL72 机柜级节点的价值不在单请求解码，而在把“采样—解码—流式输出”三段放在同一 NVLink 5 域内，使 latent 不必经主机内存中转。具体例子：一条 1080p、数十秒量级的视频，其 latent 张量按公式 <span class=\"formula-inline\">$$\\text{Mem}_{\\text{latent}}\\approx \\frac{C'\\,H'\\,W'\\,T}{\\text{compression}}\\cdot b_{\\text{latent}}$$</span> 估算，压缩比与位宽共同决定能否与解码工作区同时驻留；把 latent 从 FP16 降到 FP8 直接减半该项，是把 batch 从 1 提到 2 的最省力手段，而换卡未必有这个效果。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-28\">二十八 · 并行拓扑：帧级数据并行与采样序列并行轴分离</h3>\n<p>VAE 解码的并行轴与采样阶段不同。采样阶段沿序列（时空 token）做序列并行，解码阶段则应沿时间轴做帧级数据并行：每个 rank 领取一组连续输出帧，独立完成时间上采样与空间 tile 解码，只在 halo 帧上下文处与邻 rank 交换少量 latent。这样做的原因是解码卷积的感受野在时间上有限，帧间耦合弱于采样注意力的全序列耦合，切分代价低。</p>\n<p>伪代码思路：按帧块划分，rank r 负责帧区间 [t0, t1)，额外读取前后各若干 halo 帧的 latent；时间上采样层用重叠帧上下文融合，保证块边界不闪烁；空间上按 tile 分块，tile 间 halo 不少于卷积感受野。代价是 halo 帧的重复读取与重复计算，重复比例约为 halo 帧数除以本 rank 帧数——帧块越短，重复开销占比越高，因此帧块长度应与 halo 深度匹配，而不是越小越好。</p>\n<p>拓扑上要避免把解码帧并行与采样序列并行混在同一通信组：采样阶段的集合通信是大消息、低频次，解码阶段的 halo 交换是小消息、高频次，混组会让 NCCL 通道争用。工程判断是给解码单独划一个子通信域，halo 交换走点对点或小规模 all-to-all，与采样阶段的张量并行流量在物理上错开。显存代价方面，帧级并行使每 rank 只需持有自己帧区间的解码激活与 tile 工作区，工作区随 tile 尺寸平方增长，因此 tile 尺寸是并行度之外的第二个显存旋钮。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-29\">二十九 · 量化方案：per-group scale 的分组粒度决定纹理保真度</h3>\n<p>latent 量化的核心不是选 FP8 还是更低 bit，而是分组粒度。分组量化写为：</p>\n<div class=\"formula\">$$\\hat{x}=\\text{clip}\\left(\\text{round}\\left(\\frac{x}{s_g}\\right),q_{\\min},q_{\\max}\\right)\\cdot s_g,\\quad s_g=\\frac{\\max_{i\\in g}|x_i|}{q_{\\max}}$$</div>\n<p>latent 通道间动态范围差异大，按通道分组（而非整张量一个 scale）是必须的；组越细，量化误差越小，但 scale 的存储与反量化开销上升。工程上的配方是：latent 缓存用 FP8 加 per-channel-group scale，解码首层做反量化并把残差 <span class=\"formula-inline\">$$x-\\hat{x}$$</span> 补偿进去；解码卷积本身用 FP8，权重侧用 per-channel scale。这样把误差集中补偿在首层，而不是让低 bit 误差在多层卷积中累积放大。</p>\n<p>代价要算清楚：低 bit latent 减少的是 HBM 读取字节与缓存占用，直接改善公式中的带宽项与显存项；但反量化与残差补偿在解码首层引入额外计算与一次额外读取，若首层本身已是计算瓶颈，这部分开销会体现在帧间隔上。具体例子：文字与高频纹理区域是失败模式的高发区，per-group scale 在这些通道上若组过粗，会出现模糊与振铃，且后处理无法完全恢复——因此对含文字的场景应缩小分组粒度或对该段 latent 保留更高位宽，这是精度分配问题，与稀疏注意力那类按层分配的思路同源但作用在通道维。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-30\">三十 · KV 策略：这里没有 KV，只有滚动回收的 latent 缓存</h3>\n<p>本方案不涉及 KV cache，替代它的是 latent 缓存的生命周期管理。缓存按块或按帧滚动回收：解码器按时间块流式读取 latent，读完即释放该块，只保留 halo 帧所需的尾部上下文；输出像素按帧流式写出，不驻留整段视频。这样显存占用与视频总时长解耦，只与块大小、halo 深度、并行度相关。</p>\n<p>滚动回收的工程细节在于回收时机与异步拷贝的同步点。异步拷贝把 latent 从 HBM 搬到 SMEM 与 FP8 卷积计算重叠，若在拷贝未完成时回收源块，会读到已释放内存；正确做法是用事件或屏障把回收绑在拷贝完成之后，而不是绑在计算完成之后。失败模式很明确：同步点设置不当会让 SMEM 读写竞争，解码反而变慢。带宽代价上，滚动回收让 HBM 读流量近似等于 latent 总字节数乘以（1 + halo 重复率），重复率由块长与 halo 深度之比决定，这是吞吐的上限约束之一。</p>\n<p>与自回归视频 2bit KV 量化那条线不同，这里没有随生成步增长的缓存，缓存大小在请求开始时就由分辨率与时长确定，因此容量规划可以直接用上面的显存公式做静态预算，而不需要按步做动态水位管理。这也是它适合流式输出的原因：首帧时延只取决于第一个时间块的 latent 读取与解码，不依赖后续块。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-31\">三十一 · 调度参数：以首帧时延与帧间隔为 SLO 的两个独立旋钮</h3>\n<p>调度上要把首帧时延与帧间隔分开治理，因为它们由不同资源决定。首帧时延由第一个时间块的 latent 读取、首层反量化补偿与一次完整 tile 解码构成，受 tile 尺寸与 halo 深度影响；帧间隔由稳态下的 FP8 卷积吞吐与异步拷贝重叠效率决定，受 SMEM 容量与同步点影响。把两者混成一个“端到端时延”指标去调参，会出现在 tile 变小改善首帧、却因 halo 重复计算拖垮帧间隔的情况。</p>\n<p>批调度参数上，批大小受 latent 缓存与解码工作区显存约束，低 bit latent 使更长视频或更大 batch 可驻留；连续批处理在解码阶段的意义有限，因为解码是按帧流式推进的流水线，更适合用固定并发加帧级流水槽位，而不是按请求动态拼批。具体例子：当并发请求的分辨率差异大时，按 latent 字节数而非请求数做准入控制，避免一个大分辨率请求把工作区显存吃满导致其他请求的 tile 退化。功耗侧，FP8 卷积把解码推入计算受限后，SM 利用率上升、帧间隔更稳定，但持续高占用会让功耗逼近档位上限，此时降 tile 尺寸比降并行度更能平滑功耗曲线。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-32\">三十二 · 可复现的配置思路：从单卡基线到机柜级的三步走</h3>\n<p>给出一个可复现的配置路径，按顺序做三步，每步都有明确的判据与回退点。</p>\n<ul>\n<li>第一步，单卡基线：latent 用 FP8 加 per-channel-group scale，解码卷积 FP8，tile 尺寸取使工作区显存占单卡约一半的值，halo 不少于卷积感受野。测量解码阶段 HBM 带宽是否接近峰值，若是则进入第二步调重叠，若不是则直接进入第三步评估并行。</li>\n<li>第二步，重叠与残差：开启异步拷贝到 SMEM 与 FP8 卷积重叠，同步点绑在拷贝完成事件上；首层加残差补偿。判据是帧间隔是否下降且 tile 边界无接缝、块边界无闪烁；若变慢，检查 SMEM 读写竞争与同步点位置。</li>\n<li>第三步，拓扑扩展：仅在解码确为计算受限时启用帧级数据并行，帧块长度与 halo 深度匹配，halo 交换走独立子通信域；在 NVL72 上把采样与解码放在同一 NVLink 域内以避免主机内存中转。</li>\n</ul>\n<p>量化方案的回退点是分组粒度：纹理与文字区域出现模糊或振铃时，先缩小组粒度，再考虑对问题段保留更高位宽，而不是整体退回 FP16——整体退回会让带宽项重新占优，丢掉把解码推向计算受限的收益。稳定性技巧上，halo 重叠不少于卷积感受野是硬约束，时间上采样必须用重叠帧上下文融合，残差必须在首层补偿，这三条任一缺失都会以接缝、闪烁或模糊的形式暴露，且无法靠后处理修复。规模上限由高压缩比 VAE 的重建保真度与低 bit 量化误差共同决定，因此配置思路的终点不是“更大并行度”，而是在给定保真度预算下找到 tile、halo、分组粒度三者的最小可行组合。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-33\">三十三 · 解码端配方的失效边界与系统代价</h3>\n<p>这套配方把 VAE 解码从“整帧一次性”改成“按时间块与空间 tile 滚动”，其收益上限由两个量夹住：一是高压缩比 VAE 的重建保真度，二是低 bit latent 的量化误差。分组量化写成 <span class=\"formula\">$$\\hat{x}=\\text{clip}\\left(\\text{round}\\left(\\frac{x}{s_g}\\right),q_{\\min},q_{\\max}\\right)\\cdot s_g,\\quad s_g=\\frac{\\max_{i\\in g}|x_i|}{q_{\\max}}$$</span>，$g$ 按通道分组正是为了吃掉 latent 通道间的动态范围差异；但残差 $x-\\hat{x}$ 只在解码首层补偿一次，纹理与文字区域的高频分量一旦被量化抹平，后处理无法重建，表现为模糊与振铃。因此适用边界很明确：分辨率与时长越大、解码占端到端时延比重越高，收益越显著；而文字密集、高频纹理为主的素材属于该配方的失效区，应退回 FP16 latent 或提高 bit 宽，代价是 latent 缓存与传输量按 <span class=\"formula\">$$\\text{Mem}_{\\text{latent}}\\approx \\frac{C'\\,H'\\,W'\\,T}{\\text{compression}}\\cdot b_{\\text{latent}}$$</span> 线性上升，直接压缩可驻留的 batch 与最大帧数。</p>\n<p>分块流式解码的第二条边界在 halo。空间 tile 的 halo 重叠必须不小于卷积感受野，否则 tile 边界出现接缝或亮度跳变；而 tile 越小，重叠重复计算占比越高，吞吐按重叠比例下降。设 tile 边长 $t$、halo 宽度 $h$，重复计算比例近似为 $1-(t/(t+2h))^2$，这是吞吐的硬上限，调小 tile 换显存的做法在 $h$ 固定时会迅速吃掉收益。时间轴上同理：上采样层若不用重叠帧上下文融合，块边界闪烁无法靠后处理消除。工程判断是把 tile 与时间块尺寸设为“刚好装进解码工作区显存”的最大值，而不是最小可用值。</p>\n<p>第三条边界是异步拷贝与 FP8 卷积的同步点。解码时延近似 <span class=\"formula\">$$T_{\\text{decode}}\\approx \\max\\left(\\frac{\\text{FLOPs}_{\\text{VAE}}}{\\text{TC}_{\\text{FP8}}},\\ \\frac{\\text{Bytes}_{\\text{latent}}}{\\text{BW}}\\right)$$</span>，配方意图是把前者变成瓶颈、让后者被掩盖；但若 SMEM 读写与卷积的同步点设置不当，双缓冲退化为串行，SMEM 读写竞争反而拖慢解码。并行拓扑上 VAE 解码按帧做数据并行、与采样阶段的序列并行轴分离，意味着解码卡组的负载由帧率而非序列长度决定，帧间隔稳定性取决于最慢 tile 的尾部延迟。latent 缓存按块或按帧滚动回收，KV 不涉及；SLO 以首帧时延与帧间隔为主，首帧收益来自低 bit latent 更早写完缓存，而帧间隔收益来自计算受限后的稳定流水。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测现象</th><th>系统代价</th></tr></thead><tbody><tr><td>低 bit 下文字/高频纹理</td><td>模糊、振铃，残差补偿不足</td><td>需回退更高 bit，latent 显存与带宽上升</td></tr><tr><td>halo 小于感受野</td><td>tile 接缝、亮度跳变</td><td>增大 halo，重复计算占比上升、吞吐下降</td></tr><tr><td>同步点设置不当</td><td>拷贝与卷积串行化</td><td>解码退回带宽受限，帧间隔抖动</td></tr></tbody></table>\n<h3 id=\"alg-vae-decode-2bit-latent-sec-34\">三十四 · 显存驻留与batch上限：先崩的是latent缓存</h3>\n<p>规模上去以后，第一个撞墙的不是算力，而是显存驻留能力。解码端要同时容纳三类东西：采样输出的低bit latent缓存、解码工作区（SMEM与tile中间激活）、以及按帧滚动输出的像素缓冲。前者的量级由压缩比与量化位宽共同决定：</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{latent}}\\approx \\frac{C'\\,H'\\,W'\\,T}{\\text{compression}}\\cdot b_{\\text{latent}}$$</div>\n<p>压缩比提高与$b_{\\text{latent}}$从FP16降到FP8，是同一枚硬币的两面——它们共同把latent驻留压到可接受区间，从而让更长视频或更大batch留在卡上。但要注意这里的非线性：batch增大时latent缓存线性增长，解码工作区却随tile数与并发帧数增长，两者叠加后显存曲线比单请求时陡。工程判断是：先按“latent缓存占大头、工作区占小头”的假设做容量规划，再在真实分辨率下实测工作区峰值；若工作区反超，说明tile切得过细或并发帧过多，应优先放大tile而非加卡。具体例子：一条高分辨率长视频流式解码请求，若把batch从1提到4，latent缓存翻四倍而工作区只翻一倍左右，显存瓶颈会从工作区转移到latent缓存，此时降低$b_{\\text{latent}}$（FP8→更低bit）比缩小tile更有效。</p>\n<p>代价落在吞吐上：batch上限被latent缓存锁死时，GPU的FP8卷积单元利用率上不去，解码从计算受限退回带宽受限，帧间隔抖动变大。这就是“规模上去先崩显存”的第一层含义。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-35\">三十五 · 带宽与计算受限的切换点</h3>\n<p>解码时延的解析式给出两个竞争项：</p>\n<div class=\"formula\">$$T_{\\text{decode}}\\approx \\max\\left(\\frac{\\text{FLOPs}_{\\text{VAE}}}{\\text{TC}_{\\text{FP8}}},\\ \\frac{\\text{Bytes}_{\\text{latent}}}{\\text{BW}}\\right)$$</div>\n<p>低bit latent直接压第二项，FP8卷积与异步拷贝重叠则抬第一项的有效吞吐。切换点的工程意义在于：当$\\text{Bytes}_{\\text{latent}}/\\text{BW}$占主导时，加算力无用，只能降位宽或提压缩比；当$\\text{FLOPs}_{\\text{VAE}}/\\text{TC}_{\\text{FP8}}$占主导时，降位宽收益递减，应转向tile调度与SMEM复用。规模上去后，分辨率与时长同时增长，FLOPs按$H'W'T$增长、Bytes按同比例但除以压缩比增长，两者比值近似不变——真正改变切换点的是$b_{\\text{latent}}$与压缩比。因此容量规划必须回答：在当前压缩比下，解码是带宽受限还是计算受限？若是前者，FP8卷积只是锦上添花；若是后者，异步拷贝的重叠深度才是关键。</p>\n<p>具体机制上，异步拷贝把latent块从HBM搬到SMEM，与FP8卷积计算重叠；若同步点设置不当，SMEM读写竞争会让解码变慢而非加速。代价是SMEM容量被双缓冲占用，tile尺寸受限于SMEM上限，进而影响halo重叠比例。具体例子：时间块流式读取时，若每块只预取一块而不做双缓冲，卷积等待拷贝完成，解码退化为串行，帧间隔被拷贝延迟主导；改为双缓冲后，拷贝与计算并行，帧间隔趋于稳定。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-36\">三十六 · 通信：latent传输与解码并行的拓扑约束</h3>\n<p>latent传输量随压缩比与位宽下降，但通信模式并未消失。分离式部署中，采样节点产出latent、解码节点消费latent，跨节点传输的是低bit latent块而非像素，这使NVLink 5与NIXL上的传输窗口变窄、首帧等待缩短。规模上去后，通信瓶颈从“传不动”转为“传得碎”：按帧或按块滚动回收的latent缓存若切得过细，小消息占比升高，NCCL集合通信的效率下降，解码节点出现饥饿。</p>\n<p>并行拓扑上，VAE解码按帧做数据并行，与采样阶段的序列并行轴分离——这意味着解码侧的通信是帧间独立的all-to-all或点对点，而非序列维的规约。工程判断：把解码数据并行的分组大小对齐到单节点内NVLink域，跨节点只传latent块不传中间激活，可避免解码并行度提升时通信量同步膨胀。代价是解码节点数增加后，latent缓存的滚动回收需跨节点协调，回收滞后会造成显存碎片。具体例子：NVL72机架内做帧级数据并行，每帧解码独立、halo只在帧内tile间重叠，跨帧无通信；一旦跨机架扩规模，latent块需经NIXL搬运，首帧时延由最慢一跳决定，尾延迟被通信抖动放大。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-37\">三十七 · 功耗与热约束下的持续吞吐</h3>\n<p>FP8卷积把解码从带宽受限推向计算受限，直接后果是SM功耗密度上升。带宽受限时，HBM读写占功耗大头且相对平稳；计算受限时，张量核心持续高负载，功耗随tile调度波动。规模上去后，持续吞吐受功耗墙约束：单卡功耗上限固定，解码并行度提高会摊薄每帧的功耗预算，若tile过小导致halo重复计算占比升高，无效FLOPs直接转化为无效功耗，吞吐不升反降。</p>\n<p>机制上，halo重叠不少于卷积感受野是正确性下限，但重叠比例决定重复计算开销上限。tile越小，halo占tile面积的比例越高，重复计算越多，功耗中无效部分越大。工程判断：在满足感受野的前提下取尽量大的tile，把halo开销压到可忽略比例；若显存或SMEM限制迫使tile变小，应改用时间维分块而非空间维细分，因为时间上采样的重叠帧上下文融合本身就需要跨块上下文，重复计算可被融合逻辑吸收。代价是时间块变大后首帧时延上升，流式输出的启动变慢。具体例子：空间tile从较大尺寸减半，halo面积占比约翻倍，解码FLOPs中重复部分显著上升，帧间隔变长且功耗曲线出现尖峰。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-38\">三十八 · 尾延迟：规模上去后最先劣化的SLO指标</h3>\n<p>首帧时延与帧间隔是这类负载的主SLO。平均吞吐好看不代表SLO达标，规模上去后尾延迟先崩，原因有三：其一，latent缓存滚动回收若滞后，偶发的显存分配失败触发同步等待，单帧时延出现长尾；其二，tile边界接缝与时间块闪烁的修复依赖重叠帧上下文，块边界处的融合计算比块内重，形成周期性的帧间隔尖峰；其三，异步拷贝与FP8卷积的同步点在高并发下争用SMEM，个别帧的拷贝延迟被放大。</p>\n<p>失败模式的定性描述很明确：halo重叠小于卷积感受野时tile边界出现接缝或亮度跳变；时间上采样未用重叠帧上下文融合时块边界闪烁；残差首层补偿不足时文字与高频纹理出现模糊与振铃，且后处理无法完全恢复。这些都不是平均指标能捕获的，必须在尾部分位上观测。工程判断：把帧间隔的P99而非均值作为扩容判据；当P99随batch上升而劣化，说明回收或同步点已成瓶颈，此时加卡不如改调度——例如把latent缓存按帧预分配、把同步点从每tile一次改为每时间块一次。具体例子：长视频流式解码中，块边界帧的间隔明显高于块内帧，若把时间块长度对齐到上采样倍数的整数倍，边界帧的融合开销可被摊薄，尾部尖峰收窄。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-39\">三十九 · 规模上限由谁决定</h3>\n<p>把五条线放在一起看，规模上限的排序是：显存驻留先于带宽、带宽先于通信、通信先于功耗、功耗先于尾延迟的SLO违约。latent缓存决定batch上限，$b_{\\text{latent}}$与压缩比决定带宽切换点，解码数据并行的拓扑决定通信是否随规模膨胀，tile与halo比例决定无效功耗上限，而回收与同步点决定尾延迟。高压缩比VAE的重建保真度与低bit量化误差是硬边界：文字与高频纹理场景下，残差首层补偿只能缓解不能消除，规模再大也换不回细节。</p>\n<p>因此扩容的正确顺序不是先加卡，而是先确认当前瓶颈落在哪一项：若$\\text{Bytes}_{\\text{latent}}/\\text{BW}$主导，降位宽或提压缩比；若工作区反超latent缓存，放大tile；若P99帧间隔随batch劣化，改回收策略与同步粒度。只有当解码确已计算受限且tile与halo比例已优化到下限，增加解码并行度才带来线性吞吐。这条判断链把“哪里先崩”从定性直觉变成可测的切换点，也是容量规划在Blackwell上落地时唯一可靠的顺序。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-40\">四十 · 规模上去以后，先崩的是 latent 带宽与 halo 重复计算</h3>\n<p>把高压缩 VAE 与低 bit latent 放进真实服务链路，第一处失效点不在算力，而在 <code>Mem_latent</code> 与 <code>Bytes_latent</code> 的同步膨胀。按给定公式，latent 缓存占用随 <code>C'H'W'T/compression·b_latent</code> 线性增长：分辨率翻倍、时长翻倍，即使压缩比与位宽不变，缓存也按四倍量级上涨，而批大小与滚动回收窗口被这块常驻显存直接锁死。解码时延则由 <code>max(FLOPs_VAE/TC_FP8, Bytes_latent/BW)</code> 决定，低 bit latent 与 FP8 卷积把前者推高、把后者压低，系统从带宽受限滑向计算受限——这正是帧间隔变稳的来源，也是新瓶颈的来源：一旦跨过交点，再压位宽只减带宽不减 FLOPs，收益迅速饱和。工程判断是先用 <code>Bytes_latent/BW</code> 与 <code>FLOPs_VAE/TC_FP8</code> 两条曲线估交点，再决定是继续降 bit 还是改 tile 与并行拓扑。</p>\n<p>第二处失效点是空间 tile 的 halo 重复计算。设 tile 边长 <code>L</code>、卷积感受野 <code>r</code>、halo 宽度取 <code>h≥r</code>，则有效计算量放大约为 <code>((L+2h)/L)²</code>；<code>L</code> 越小，重叠占比越高，吞吐按平方级下降。halo 小于感受野时，tile 边界直接出现接缝或亮度跳变，这类缺陷无法靠后处理修补。时间轴上同理：时间上采样层若不用重叠帧上下文融合，块边界闪烁；而异步拷贝与 FP8 卷积的重叠若同步点设置不当，SMEM 读写竞争会让解码变慢而非变快。因此 tile 尺寸应按“halo 占比可接受 + 单 tile 工作区显存可驻留”两条约束联合选取，而不是一味求小。</p>\n<p>第三处是量化误差在规模下的累积。分组量化 <code>x̂=clip(round(x/s_g),q_min,q_max)·s_g</code>，<code>s_g=max|x_i|/q_max</code> 按通道分组以吸收 latent 通道间动态范围差异；残差 <code>x−x̂</code> 在解码首层补偿。规模上去后，高压缩比 VAE 本身的重建损失与低 bit 量化误差叠加，在文字与高频纹理区域表现为模糊与振铃，残差首层补偿不足时后处理无法恢复——这是保真度上限，不是吞吐问题，须在 SLO 层面按场景分级：纹理敏感请求走高 bit latent 或更高保真 VAE，其余走低 bit 快路径。</p>\n<p>并行与通信侧，VAE 解码按帧做数据并行，与采样阶段的序列并行轴分离，避免两套并行拓扑互相牵制；单卡或单节点多卡档位下，帧级并行几乎不引入跨卡通信，但每卡仍需独立 latent 缓存与解码工作区，显存随卡数线性分摊而非共享。功耗上，FP8 卷积把解码推向计算受限后，SM 利用率上升、单位帧能耗更可预测，但 halo 重复计算会直接抬高总 FLOPs，抵消部分能效收益。尾延迟主要来自首帧：流式输出让首帧只依赖首个时间块与首层反量化，块越小首帧越快，代价是 halo 开销与块边界融合成本上升；稳态帧间隔则由 tile 尺寸与 SMEM 竞争决定。规模上限最终由高压缩比 VAE 的重建保真度与低 bit 量化误差共同划定，而非由算力或带宽单独决定。</p>\n<h3 id=\"alg-vae-decode-2bit-latent-sec-41\">四十一 · 精度失效的三条链路：分组量化、残差补偿与首层反量化</h3>\n<p>低 bit latent 解码的精度问题不是单一“量化误差”能概括的，它在数据流上有三条独立的失效链路，诊断时必须分开定位。第一条是分组量化的截断损失：按 <span class=\"formula-inline\">s_g = max|x_i| / q_max</span> 取组内最大绝对值做 scale，意味着组内只要有一个离群通道，其余通道的有效位宽就被压缩；latent 通道间动态范围差异大时，这种组内挤压在纹理与文字笔画区域最先显形。第二条是残差补偿的覆盖不足：残差 <span class=\"formula-inline\">x − x̂</span> 只在解码首层补偿，若首层卷积的感受野无法把残差扩散到后续上采样层，误差会在空间上采样阶段被放大成振铃。第三条是反量化与 FP8 卷积的数值路径不一致：latent 以低 bit 缓存、解码器以 FP8 计算，两次舍入的方向若不一致，会在高频处产生系统性偏置。</p>\n<p>诊断这三条链路的工程做法是分层探针而非端到端 PSNR。在 latent 缓存写入点抓取 <span class=\"formula-inline\">x̂</span> 与原始 <span class=\"formula-inline\">x</span>，按通道分组统计残差能量分布，若某一组的残差能量显著高于同层其他组，就是组内离群通道导致的 scale 失配，处置是把该组再细分或对该通道单独提精度。在解码首层输出点抓取补偿后的特征图，与 FP16 参考路径逐层比对，若首层已对齐而后续层偏差增大，问题在残差未有效扩散，需要扩大首层补偿的注入范围而不是继续调量化参数。在最终像素输出上按区域统计误差，文字与高频纹理区域误差集中而平坦区域正常，则确认是高压缩比 VAE 的重建保真度上限，此时任何量化调参都无法恢复，只能回滚到更低压缩比或提高 latent 位宽。</p>\n<p>系统代价上，精度回滚不是免费的：把 latent 从低 bit 提到 FP8 或 FP16，<span class=\"formula-inline\">Mem_latent ∝ b_latent</span> 线性上升，直接压缩可驻留的 batch 与最长视频时长；把解码器从 FP8 卷积退回 FP16，<span class=\"formula-inline\">T_decode</span> 中计算项 <span class=\"formula-inline\">FLOPs_VAE / TC</span> 的分母减半，解码从计算受限重新滑向带宽受限，帧间隔稳定性下降。因此精度回滚应做成按请求分级的开关，而不是全局降级：对文字密集、高频纹理的请求走高位宽路径，对平坦场景维持低 bit，避免为少数失败样本牺牲整体吞吐。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-42\">四十二 · OOM 的真实来源：latent 缓存、halo 工作区与异步拷贝缓冲</h3>\n<p>OOM 在低 bit latent 解码里通常不是模型权重撑爆，而是三块动态工作区叠加。第一块是 latent 缓存，按块或按帧滚动回收，若回收时机晚于下一块的写入，缓存会随视频时长线性膨胀；低 bit 只是把斜率压低，不改变无界增长的性质。第二块是空间 tile 解码的 halo 工作区：每个 tile 需要额外驻留重叠边界的输入与中间特征，tile 越小、halo 占 tile 比例越高，工作区相对有效计算的比例越大，显存效率反而下降。第三块是异步拷贝的 SMEM 与流水缓冲，为把 HBM 读写与 FP8 卷积重叠，需要双缓冲甚至多级流水，缓冲深度乘以块大小就是一笔固定开销，在长视频流式场景下这笔开销会与 latent 缓存竞争同一显存预算。</p>\n<p>定位 OOM 要看增长斜率而非瞬时峰值。在解码循环里按帧记录已分配显存，若曲线呈阶梯上升且台阶与时间块对齐，是 latent 缓存回收滞后；若曲线在 tile 切换处出现尖峰，是 halo 工作区按最大 tile 预留而未随实际 tile 收缩；若曲线整体平移一个与流水深度成正比的常量，是异步拷贝缓冲配置过大。处置顺序应是先修回收时机（把 latent 块的释放提前到该块最后一帧输出之后立即执行），再调 tile 与 halo 比例使工作区与计算量匹配，最后才削减流水深度——削减流水会直接破坏拷贝与计算的重叠，把解码推回带宽受限。</p>\n<p>工程判断上，OOM 与批大小是耦合的：批大小受 latent 缓存与解码工作区共同约束，低 bit latent 让更长视频或更大 batch 可驻留，但 halo 工作区与流水缓冲不随位宽缩小，所以位宽下降带来的 batch 增益存在上限。容量规划时应把工作区按“每并发流固定开销 + 每帧可变开销”拆开建模，固定开销决定并发上限，可变开销决定最长时长，两者混在一起估会导致长视频请求把并发挤爆。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-43\">四十三 · 批抖动与路由不均：为什么帧间隔会周期性劣化</h3>\n<p>批抖动在流式解码里表现为帧间隔的周期性劣化，根因是解码工作量的时间不均匀性与批内请求的路由不均。时间维度上，时间上采样层需要重叠帧上下文融合，某些时间块因重叠帧数变化而计算量高于相邻块；空间维度上，tile 分块解码的 halo 重叠使边界 tile 的有效计算占比低于内部 tile。当这些不均匀块被动态批处理拼进同一批，批内最慢的那条请求决定整批完成时间，快请求被拖慢，形成抖动。</p>\n<p>路由不均则是并行拓扑问题：VAE 解码按帧做数据并行，与采样阶段的序列并行轴分离，帧到卡的映射若按连续帧切分，重叠帧上下文融合会跨卡，产生额外的跨卡同步；若按交错帧切分，单卡上的时间连续性被破坏，重叠融合退化为逐帧独立解码，块边界闪烁回归。诊断方法是按卡统计每帧的解码耗时与跨卡通信量，若某几张卡耗时显著偏高且通信量集中，是帧映射与重叠上下文冲突；若各卡耗时相近但批完成时间方差大，是批内请求的工作量分布不均。</p>\n<p>系统代价上，批抖动的直接后果是 SLO 中的帧间隔尾部超标，而平均帧间隔可能仍然好看，所以监控必须看分位数而非均值。缓解手段有两类：一是按工作量而非按到达顺序组批，把计算量相近的块拼批，牺牲一点批填充率换尾部稳定；二是对重叠帧上下文做预取，把跨块依赖提前到上一块解码期间异步完成，使块切换时的等待被隐藏。前者降低吞吐峰值，后者增加显存与带宽开销，取舍取决于 SLO 是卡首帧还是卡帧间隔。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-44\">四十四 · 尾延迟尖刺：同步点、SMEM 竞争与 tile 边界</h3>\n<p>尾延迟尖刺与批抖动的区别在于它不是周期性的，而是由离散事件触发。最常见的触发源是异步拷贝与 FP8 卷积重叠的同步点设置不当：拷贝完成与卷积启动之间若用粗粒度屏障，SMEM 读写会在屏障处串行化，原本应重叠的 HBM 读写与计算变成交替执行，单帧耗时出现尖刺；若屏障过细，同步开销本身又成为负担。第二个触发源是 tile 边界：halo 重叠小于卷积感受野时，边界 tile 需要回退重算或引入额外填充，重算路径的耗时显著高于内部 tile，表现为随 tile 数增加而增多的尖刺。第三个触发源是 latent 缓存的滚动回收：回收动作若与解码计算在同一流上串行执行，会在回收帧处插入一段无计算的空窗。</p>\n<p>诊断尖刺要抓时间线而非聚合指标。用逐帧、逐 tile 的耗时直方图，若尖刺集中在 tile 序号为边界值的那些 tile 上，是 halo 不足；若尖刺与拷贝完成事件对齐，是同步点粒度问题；若尖刺周期性出现在固定帧间隔上，是缓存回收与计算争用同一条流。处置上，halo 应不少于卷积感受野，这是硬约束，不能靠调参绕过；同步点应细化为按缓冲区的完成事件而非全局屏障，让卷积在部分缓冲就绪时即可启动；缓存回收应放到独立流或与计算重叠的异步路径上。</p>\n<div class=\"formula\">$$T_{\\text{decode}}\\approx \\max\\left(\\frac{\\text{FLOPs}_{\\text{VAE}}}{\\text{TC}_{\\text{FP8}}},\\ \\frac{\\text{Bytes}_{\\text{latent}}}{\\text{BW}}\\right)$$</div>\n<p>这个 max 结构解释了尖刺的代价：当重叠良好时，解码耗时由两项中较大者决定，尖刺意味着某一项被短暂放大——同步点问题放大的是有效计算时间（TC 利用率下降），halo 不足放大的是重复计算量（FLOPs 分子上升），缓存回收争用放大的是有效带宽需求。三者都表现为 max 的取值上跳，但修复路径完全不同，所以监控必须能区分“计算项变大”还是“带宽项变大”，否则会把同步问题误判成量化精度问题去调 scale。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-45\">四十五 · 监控指标体系与回滚决策</h3>\n<p>监控应围绕四个维度建最小指标集，且每个指标都要能定位到上面某一类失败模式。精度维度：分组残差能量分布、首层补偿后与参考路径的逐层偏差、文字与高频区域的局部误差率——用于区分量化截断、残差扩散不足与 VAE 保真度上限。显存维度：latent 缓存按帧增长斜率、halo 工作区峰值、流水缓冲常量占用——用于区分三类 OOM。时延维度：首帧时延、帧间隔分位数（而非均值）、逐 tile 耗时直方图——用于区分批抖动与尾延迟尖刺。路由维度：按卡的帧耗时与跨卡通信量——用于识别帧映射与重叠上下文冲突。</p>\n<p>回滚决策要按失败模式分级，而不是一刀切降级。精度类失败中，若残差能量集中在少数通道组，回滚动作是细分分组或对该组提位宽，代价是 <span class=\"formula-inline\">Mem_latent</span> 小幅上升；若误差集中在文字高频区域且分层探针显示首层已对齐，说明是 VAE 重建上限，回滚动作是切到更低压缩比路径，代价是 latent 缓存与传输量整体上升、batch 上限下降。显存类失败优先修回收时机与 tile 比例，这两项不改变数值路径，回滚成本最低；削减流水深度是最后手段，因为它直接损害重叠。时延类失败中，同步点细化与 halo 补足属于配置修正而非回滚；只有当批抖动无法通过组批策略压住尾部时，才回滚到更保守的批大小，代价是吞吐下降。</p>\n<p>回滚必须可灰度：按请求特征（分辨率、时长、是否含文字密集内容）路由到不同精度与分块配置，而不是全局切换。这样精度失败只影响少数请求，OOM 与尖刺修复也不必让全体请求承担吞吐损失。灰度路由本身需要监控覆盖，否则会出现同一集群内两套配置的指标混在一起、无法归因的情况。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>首选处置</th><th>系统代价</th></tr></thead><tbody><tr><td>分组量化截断</td><td>某通道组残差能量偏高</td><td>细分分组或单通道提位宽</td><td>latent 显存小幅上升</td></tr><tr><td>残差补偿不足</td><td>首层对齐、后续层偏差增大</td><td>扩大首层补偿注入范围</td><td>首层计算量增加</td></tr><tr><td>VAE 保真度上限</td><td>文字高频区域误差集中</td><td>切更低压缩比路径</td><td>缓存与传输量上升、batch 下降</td></tr><tr><td>latent 缓存滞后</td><td>显存阶梯上升对齐时间块</td><td>提前释放该块最后一帧后缓存</td><td>无额外计算代价</td></tr><tr><td>halo 不足</td><td>边界 tile 耗时尖刺</td><td>halo 补足至感受野</td><td>重复计算占比上升</td></tr><tr><td>同步点过粗</td><td>尖刺对齐拷贝完成事件</td><td>按缓冲区完成事件细化</td><td>同步开销略增</td></tr></tbody></table>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-46\">四十六 · 把诊断做成解码循环的一部分</h3>\n<p>上述诊断若只在离线做，失败模式会在生产里以尾延迟和画质投诉的形式暴露，归因成本极高。可行做法是把探针嵌入解码循环的低频路径：每 N 个时间块抓一次分组残差能量与首层偏差，每帧记录 tile 耗时与拷贝完成时刻，缓存回收点记录分配器水位。这些探针本身有代价——抓取中间特征会打断异步拷贝与计算的重叠、增加 SMEM 占用——所以采样率必须可调，且在 SLO 紧张时自动降频，避免监控本身成为尾延迟尖刺的来源。</p>\n<p>更关键的是把回滚判据写成可执行的阈值规则而非人工判断：分组残差能量超过同层中位数的倍数、边界 tile 耗时超过内部 tile 的固定比例、帧间隔某分位数连续多个窗口超标，各自触发对应的配置修正或灰度切换。规则要绑定到具体机制而不是笼统的“质量下降”，否则运维只能全局降级。最终落在工程判断上：低 bit latent 解码的稳定性不取决于量化位宽选得多低，而取决于失败模式是否被拆成可独立观测、可独立回滚的链路——精度三条链、显存三块工作区、时延两类尖刺源，每一条都有对应的探针与代价可控的处置，这套拆解本身就是容量规划与 SLO 承诺的前提。</p>\n<h3 id=\"alg-vae-decode-2bit-latent-sec-47\">四十七 · 对照轴：压缩发生在哪一端</h3>\n<p>把相邻算法放在同一张坐标纸上，第一个轴不是“用了什么精度”，而是“压缩发生在采样端还是解码端”。本文这条线把压缩放在解码端：采样输出的 latent 先被分组量化写入缓存，再由分块流式解码器逐块还原。分块重叠与序列并行那条线把压力放在采样端——它解决的是采样阶段整段 latent 驻留显存与序列切分的问题，解码端仍按常规精度整帧或大块还原。NVFP4 视频 DiT 量化推理与 FP8 时空注意力内核则把量化放在采样网络内部，改变的是去噪步的算力与带宽结构，latent 本身未必被压。轨迹感知缓存复用与少步蒸馏采样压缩的是“步数”，不是“每步的数据宽度”。这四条轴互不替代：步数压缩降低总工作量，精度压缩降低单位工作量成本，解码端压缩降低输出侧驻留与传输。</p>\n<p>判断归属只需看一个量：端到端时延里 VAE 解码占比是否显著。若解码占大头，采样端再怎么优化也只是压缩剩余部分；若采样占大头，解码端低 bit 化的收益被摊薄，反而引入纹理损失。这就是为什么本片段的决策表以“解码占比”为第一分列条件，而不是以分辨率单独判断。</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{latent}}\\approx \\frac{C'\\,H'\\,W'\\,T}{\\text{compression}}\\cdot b_{\\text{latent}},\\quad T_{\\text{decode}}\\approx \\max\\left(\\frac{\\text{FLOPs}_{\\text{VAE}}}{\\text{TC}_{\\text{FP8}}},\\ \\frac{\\text{Bytes}_{\\text{latent}}}{\\text{BW}}\\right)$$</div>\n<p>上式给出两个可判定的信号。第一，压缩比与 $b_{\\text{latent}}$ 同时进入显存项，二者是乘积关系，因此“高压缩比 + FP8 latent”与“中等压缩比 + 更低 bit”在显存上可能等价，但在重建保真度上不等价——前者靠结构压缩，后者靠数值截断，后者在文字与高频纹理上更早失效。第二，解码时延是计算项与带宽项的 max，低 bit latent 把带宽项压低后，时延由 FP8 卷积的算力项接管；此时继续压 bit 宽度不再缩短时延，只增加量化误差。这条判据直接决定了下表的第二列。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-48\">四十八 · 决策表：六种情形的选型与代价</h3>\n<p>下表把同族算法按“首要瓶颈”归位。每一行给出触发条件、首选机制、必须同时开启的配套项，以及该选择带来的系统代价。表中不写“视情况而定”，因为每一行的判据都可以从 profiler 的两个数读出来：解码时延占比与 latent 缓存占用。</p>\n<table class=\"mini\"><thead><tr><th>情形</th><th>判据</th><th>首选</th><th>配套</th><th>代价</th></tr></thead><tbody>\n<tr><td>高分辨率长视频，解码占端到端大头</td><td>解码时延占比高、latent 缓存挤压 batch</td><td>高压缩 VAE + FP8 latent + 分块流式解码</td><td>halo ≥ 卷积感受野、时间上采样重叠帧融合、首层残差补偿</td><td>纹理与文字细节损失；halo 重复计算随 tile 缩小上升</td></tr>\n<tr><td>解码占比中等，采样端显存吃紧</td><td>采样激活与序列切分是主约束</td><td>分块重叠与序列并行（采样端）</td><td>解码端维持 FP16 或仅 latent 传输 FP8</td><td>解码端未减负，首帧时延改善有限</td></tr>\n<tr><td>采样算力受限、解码已足够快</td><td>去噪步的 MMA 利用率低、注意力访存密集</td><td>NVFP4 DiT 量化或 FP8 时空注意力内核</td><td>精度分配稀疏注意力控制敏感层</td><td>量化误差进入 latent 分布，解码端需容忍</td></tr>\n<tr><td>步数多、单步收益饱和</td><td>步数 × 单步时延构成主项</td><td>少步蒸馏采样 + 轨迹感知缓存复用</td><td>缓存复用需与量化精度匹配，避免复用旧 latent 放大误差</td><td>蒸馏带来分布偏移，长尾提示词质量下降</td></tr>\n<tr><td>流式输出、首帧 SLO 严格</td><td>首帧时延与帧间隔是 SLO 主体</td><td>本片段的分块流式解码 + 按帧滚动回收 latent</td><td>异步拷贝与 FP8 卷积重叠、tile 尺寸按 SMEM 容量定</td><td>tile 过小则重叠开销占比升高，吞吐下降</td></tr>\n<tr><td>文字/高频纹理为主的内容</td><td>重建保真度不可让步</td><td>放弃低 bit latent，仅用高压缩 VAE 结构压缩</td><td>解码保持 FP16，halo 加大</td><td>显存与带宽收益减半，长视频驻留能力受限</td></tr>\n</tbody></table>\n<p>表的读法是自上而下排除：先问解码是否占大头，再问采样是否受限，最后问保真度是否可让步。三问之后仍无解，说明瓶颈不在单点而在调度——此时应转向预填解码分离服务或连续批处理，而不是继续加深本条线的压缩比。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-49\">四十九 · 与采样端压缩的耦合条件</h3>\n<p>低 bit latent 与采样端量化并非正交。若 DiT 已用 NVFP4 或 FP8 输出 latent，latent 的数值分布已被截断一次；解码端再做分组量化，等于在同一张量上叠加两层舍入。分组量化写作</p>\n<div class=\"formula\">$$\\hat{x}=\\text{clip}\\left(\\text{round}\\left(\\frac{x}{s_g}\\right),q_{\\min},q_{\\max}\\right)\\cdot s_g,\\quad s_g=\\frac{\\max_{i\\in g}|x_i|}{q_{\\max}}$$</div>\n<p>其中 $g$ 为通道分组，$s_g$ 按组取最大绝对值。两层舍入的误差不会相互抵消：采样端量化误差在通道间是相关的，解码端 per-group scale 无法把它当作独立噪声摊平，残差 $x-\\hat{x}$ 在解码首层补偿时只能补回解码端引入的那一部分。工程判断是：采样端已用低 bit 输出时，解码端 latent 应停在 FP8 而不再下探，把省下的误差预算留给 halo 与时间融合；反之采样端保持高精度、解码端才可尝试更低 bit。</p>\n<p>与轨迹感知缓存复用的耦合更隐蔽。缓存复用会跳过部分去噪步、直接沿用旧 latent，若旧 latent 已被量化，复用等于把量化误差沿时间轴传播。此时应把复用粒度对齐到 latent 块边界，并在复用块进入解码前重算 per-group scale，而不是沿用缓存时的 scale。代价是每块多一次归约，但避免了块间亮度漂移——后者在流式输出中表现为可见的帧间跳变，后处理无法完全消除。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-50\">五十 · 分块重叠与序列并行的分工线</h3>\n<p>两条线都涉及“切块”，但切的对象不同。序列并行切的是采样阶段的序列轴，切分后各卡持有不同的 token 段，通信发生在注意力与归一化处；本片段切的是解码阶段的空间 tile 与时间块，切分后各 tile 独立卷积，靠 halo 重叠保证接缝一致，通信只发生在边界像素的融合。因此并行拓扑上二者可叠加：采样按序列并行，解码按帧做数据并行，两条轴分离，互不引入额外集合通信。</p>\n<p>分工的量化判据是 halo 开销比。设 tile 边长为 $L$、halo 宽度为 $h$，则重复计算比例近似为 $1-(L/(L+2h))^2$（二维 tile 情形）。halo 不得小于卷积感受野，否则边界出现接缝或亮度跳变；但 $L$ 缩小会让该比例迅速上升，吞吐下降。工程上把 $L$ 定在使 halo 开销占比低于总解码工作量的一小部分，再靠异步拷贝把 halo 区域的 HBM 读取藏在 FP8 卷积之后——这正是把解码从带宽受限推向计算受限的具体手段。若同步点设置不当，SMEM 读写竞争会让重叠失效，解码反而变慢，这是该机制最常见的失效路径。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-51\">五十一 · 精度分配：哪些层不能压</h3>\n<p>本条线的精度分配不是全图统一 FP8。解码器首层承担低 bit 反量化残差补偿，必须保留足够位宽以容纳 $x-\\hat{x}$；时间上采样层参与重叠帧融合，其输出直接决定块边界是否闪烁，量化误差在此处会被时间融合放大为可见的亮度波动；空间上采样的最后一层决定输出像素，纹理与文字的高频分量集中于此。这三处是精度分配的保护区，其余中间层可放心走 FP8 卷积。</p>\n<p>与精度分配稀疏时空注意力那条线的交界在于：后者在采样网络内部按层分配精度，本条线在解码网络内部按层分配精度，两者共享“敏感层不压”的原则，但敏感层的判据不同——前者看注意力对长程依赖的贡献，后者看该层输出是否直接暴露给像素或时间融合。把两条线的保护区混为一谈，会导致解码端在首层就丢掉残差补偿能力，表现为文字区域模糊与振铃，且无法通过后处理恢复。系统代价上，保护区层用 FP16 会拉高解码的算力项，使 $T_{\\text{decode}}$ 的 max 重新偏向计算侧；因此保护区应尽量窄，只覆盖上述三处，而不是整段解码器。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-52\">五十二 · 规模上限与退出条件</h3>\n<p>本条线的收益随分辨率与时长增大，但上限由两个量封顶：高压缩比 VAE 的重建保真度，与低 bit 量化误差在敏感内容上的可见度。前者是结构性的，压缩比再提高，细节损失不可逆；后者是数值性的，可通过保护区与残差补偿缓解，但不能消除。当内容以文字、细密纹理、快速运动的高频细节为主时，收益曲线会提前拐平——此时继续加深压缩比只增加失败模式，不增加吞吐。</p>\n<p>退出条件可写成三条可观测判据：其一，解码时延已不再是端到端 max 项，继续压 latent 位宽不改变 $T_{\\text{decode}}$；其二，halo 开销占比随 tile 缩小而上升，吞吐不升反降；其三，残差首层补偿后仍有可见模糊或振铃，说明误差已超出补偿能力。命中任一条，应停止加深本条线，把预算转向采样端的少步蒸馏或缓存复用，或转向服务层的预填解码分离与批调度。规模上限最终落在“保护区层位宽 × halo 比例 × 压缩比”三者的可行组合上，而不是单一的最低位宽。</p>\n\n<h3 id=\"alg-vae-decode-2bit-latent-sec-53\">五十三 · 选型边界：什么条件下该走低bit latent解码，什么条件下该退回去</h3>\n<p>与同族方案对照，先看瓶颈落在哪一段。分块重叠与序列并行优化的是采样端的激活显存与去噪时延，KV 不涉及、latent 缓存也不在它们的优化面上；常规 FP16 VAE 解码则把整帧一次性解码，显存峰值与访存字节都随分辨率线性抬升。本方案的位置很明确：只动解码端，用高压缩比 VAE 压 latent 通道与时空维度、用 FP8/低bit 缓存与传输、用 halo 重叠替代整帧解码。判据是解码时延占比——当 <span class=\"formula\">$$T_{\\text{decode}}\\approx \\max\\left(\\frac{\\text{FLOPs}_{\\text{VAE}}}{\\text{TC}_{\\text{FP8}}},\\ \\frac{\\text{Bytes}_{\\text{latent}}}{\\text{BW}}\\right)$$</span> 中第二项主导时，低bit latent 直接削减分子 Bytes，收益随分辨率与时长放大；若第一项已主导，量化只减少搬运而不减少卷积量，收益退化为显存与 batch 容量，帧间隔改善有限。</p>\n<p>失效条件集中在保真度与几何比例两处。高压缩比 VAE 叠加低bit latent 后，文字与高频纹理的重建损失无法靠后处理完全恢复，残差首层补偿不足时出现模糊与振铃；此时应退回更高 bit 的 latent 或降低压缩比，代价是 <span class=\"formula\">$$\\text{Mem}_{\\text{latent}}\\approx \\frac{C'\\,H'\\,W'\\,T}{\\text{compression}}\\cdot b_{\\text{latent}}$$</span> 中的 $b_{\\text{latent}}$ 与压缩比分母同时变大，可驻留帧数与 batch 上限随之收缩。空间侧，halo 重叠小于卷积感受野时 tile 边界出现接缝或亮度跳变；tile 越小，重叠重复计算占比越高，吞吐下降。时间侧，上采样层缺重叠帧上下文融合则块边界闪烁；异步拷贝与 FP8 卷积的同步点设置不当，SMEM 读写竞争会拖慢而非加速解码。</p>\n<p>决策表按场景取舍：</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>选择</th><th>主要代价</th></tr></thead><tbody><tr><td>高分辨率长视频、解码占端到端大头、可接受轻微纹理损失</td><td>高压缩 VAE + FP8/低bit latent + 分块流式解码</td><td>halo 重复计算、首层残差补偿开销</td></tr><tr><td>文字/高频纹理为主、保真度优先</td><td>降低压缩比或提高 latent bit，保留整帧或大 tile 解码</td><td>latent 显存与传输回升，batch 与流式首帧变差</td></tr><tr><td>瓶颈在采样端激活显存</td><td>分块重叠与序列并行，本方案仅作配套</td><td>解码端收益有限，勿在此处投入调优</td></tr><tr><td>显存极紧、帧间隔 SLO 宽松</td><td>小 tile + 低bit latent，接受吞吐折损</td><td>重叠重复计算占比升高，吞吐下降</td></tr></tbody></table>\n<p>工程判断落在两个比例上：tile 尺寸相对卷积感受野决定重复计算开销上限，per-group scale 的通道分组粒度决定动态范围差异下的量化误差分布。部署上 VAE 解码按帧做数据并行，与采样阶段的序列并行轴分离，latent 缓存按块或按帧滚动回收；单卡或单节点多卡即可承载，无需跨节点通信介入解码路径。规模上限由高压缩比 VAE 的重建保真度与低bit 量化误差共同封顶，越过这条线，任何调度技巧都换不回可用的画面。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · 少步蒸馏与轨迹缓存复用</td></tr><tr><td>解决什么</td><td>视频VAE解码在高分辨率长视频上占端到端时延与显存的大头，latent通道多、解码卷积/注意力访存密集；同时laten…</td></tr><tr><td>一句话机制</td><td>用高压缩比视频VAE把latent通道/时空维度进一步压缩，latent以FP8/低bit缓存与传输，解码器用分块流式…</td></tr><tr><td>代价与失效</td><td>高压缩比VAE重建细节损失，低bit latent在纹理/文字区域易出现模糊，需残差补偿。；分块流式解码的halo重叠带来重复计算，til…</td></tr><tr><td>后继</td><td>动态稀疏时空注意力</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-vae-decode-2bit-latent · 共 8 个片段</p>\n";break;}}})();
